1	/*
2	 * ubus_service.c —— 对外的 ubus 接口，对象名 "desktop"。
3	 *
4	 * 方法：
5	 *   start_record        开始录音，回复 {"ok":bool,"path":str}
6	 *   stop_record         停止录音，回复 {"ok":bool,"path":str}
7	 *   get_status          回复 {"recording":bool,"path":str}
8	 *   set_hint  {"text"}  设置中央提示文字（控制 UI）
9	 *   set_emoji {"name"|"id"}  立即全屏循环播放动态表情（触屏退出）：
10	 *                            name 按文件名（如 "drink"，自动补 .webp）；
11	 *                            id 按数字编号（如 5 → "05.webp"）。
12	 *                            全双工对话中(talking)拒绝，ok=false,reason="busy"。
13	 *   ask_text  {"text"}  文字问答：传一句文字 → 豆包回文字气泡 + TTS 语音播放。
14	 *                       回复 {"ok":bool[,"reason":str]}；语音优先，全双工对话中
15	 *                       或上一条回复未播完时 ok=false,reason="busy"。
16	 *   start_talk          开始全双工语音对话（等价"开始会话"按钮），复用常驻连接
17	 *                       零等待。回复 {"ok":bool[,"reason":str]}。
18	 *   stop_talk           挂断全双工语音对话（等价"停止会话"按钮），立即静音并丢弃
19	 *                       本轮残留 TTS，连接常驻不断。回复 {"ok":bool[,"reason":str]}。
20	 *   get_time            回复 {"time":"HH:MM","date":"..."}
21	 *   get_wifi            回复 {"connected":bool,"level":int,"quality":int}
22	 *   sleep_show {…}      显示睡眠报告页（sleepd 推送）：{"ok":int,"total":double,
23	 *                       "rating":str,"date":str,"summary":str,
24	 *                       "offbed"/"duration"/"turnover"/"micro":
25	 *                       {"score":double,"max":double,"count":double,"label":str}}
26	 *                       字段均可缺省（total 缺省按四项 score 加总），回复 {"ok":bool}。
27	 *                       展示 60s 自动回主页，点击屏幕提前返回。
28	 *
29	 * 事件（其他应用可 ubus subscribe / listen）：
30	 *   desktop.record      {"state":"start"|"stop","path":str}
31	 *
32	 * 用法示例：
33	 *   ubus call desktop start_record
34	 *   ubus call desktop set_hint '{"text":"你好"}'
35	 *   ubus call desktop set_emoji '{"id":5}'
36	 *   ubus call desktop set_emoji '{"name":"drink"}'
37	 *   ubus call desktop ask_text '{"text":"今天天气怎么样"}'
38	 *   ubus call desktop start_talk
39	 *   ubus call desktop stop_talk
40	 *   ubus call desktop sleep_show '{"total":82.5,"rating":"良好","date":"2026-08-08 周六","summary":"睡眠 7.6h · 下床 1 次","offbed":{"score":26.7,"max":30,"count":1,"label":"下床次数"},"duration":{"score":27.4,"max":30,"count":7.6,"label":"睡眠时长"},"turnover":{"score":16.0,"max":20,"count":24,"label":"翻身次数"},"micro":{"score":12.4,"max":20,"count":310,"label":"微动次数"}}'
41	 *   ubus listen desktop.record
42	 */
43	#include "app.h"
44	
45	#include <libubox/blobmsg_json.h>
46	#include <libubox/uloop.h>
47	#include "libubus.h"
48	#include "doubao/voice.h"
49	
50	#include <errno.h>
51	#include <string.h>
