57	/* ---------- start_record / stop_record / get_status ---------- */
58	
59	static int m_start_record(struct ubus_context *ctx, struct ubus_object *obj,
60	                          struct ubus_request_data *req, const char *method,
61	                          struct blob_attr *msg)
62	{
63	    if (screensaver_active(s_app))
64	        screensaver_stop(s_app);
65	    bool ok = recorder_start(s_app);
66	    blob_buf_init(&s_b, 0);
67	    blobmsg_add_u8(&s_b, "ok", ok);
68	    blobmsg_add_string(&s_b, "path", s_app->rec_path);
69	    ubus_send_reply(ctx, req, s_b.head);
70	    return 0;
71	}
72	
73	static int m_stop_record(struct ubus_context *ctx, struct ubus_object *obj,
74	                         struct ubus_request_data *req, const char *method,
75	                         struct blob_attr *msg)
76	{
77	    if (screensaver_active(s_app))
78	        screensaver_stop(s_app);
79	    bool ok = recorder_stop(s_app);
80	    blob_buf_init(&s_b, 0);
81	    blobmsg_add_u8(&s_b, "ok", ok);
82	    blobmsg_add_string(&s_b, "path", s_app->rec_path);
83	    ubus_send_reply(ctx, req, s_b.head);
84	    return 0;
85	}
