91	    blob_buf_init(&s_b, 0);
92	    blobmsg_add_u8(&s_b, "recording", s_app->rec_state == REC_RECORDING);
93	    blobmsg_add_string(&s_b, "path", s_app->rec_path);
94	    ubus_send_reply(ctx, req, s_b.head);
95	    return 0;
96	}
