98	/* ---------- set_hint（控制 UI） ---------- */
99	
100	enum { HINT_TEXT, __HINT_MAX };
101	static const struct blobmsg_policy hint_policy[__HINT_MAX] = {
102	    [HINT_TEXT] = { .name = "text", .type = BLOBMSG_TYPE_STRING },
103	};
104	
105	static int m_set_hint(struct ubus_context *ctx, struct ubus_object *obj,
106	                      struct ubus_request_data *req, const char *method,
107	                      struct blob_attr *msg)
108	{
109	    struct blob_attr *tb[__HINT_MAX];
110	    blobmsg_parse(hint_policy, __HINT_MAX, tb, blob_data(msg), blob_len(msg));
111	    if (!tb[HINT_TEXT])
112	        return UBUS_STATUS_INVALID_ARGUMENT;
113	
114	    if (screensaver_active(s_app))
115	        screensaver_stop(s_app);
116	    ui_set_hint(s_app, blobmsg_get_string(tb[HINT_TEXT]));
117	
118	    blob_buf_init(&s_b, 0);
119	    blobmsg_add_u8(&s_b, "ok", 1);
120	    ubus_send_reply(ctx, req, s_b.head);
121	    return 0;
122	}
