124	/* ---------- set_emoji（主动全屏播放动态表情） ----------
125	 * 两种寻址择一：
126	 *   {"name":"drink"}  按文件名（自动补 .webp），可播任意命名表情
127	 *   {"id":5}          数字编号，等价于 name="05"
128	 * 二者都给时以 name 优先。 */
129	
130	enum { EMOJI_NAME, EMOJI_ID, __EMOJI_MAX };
131	static const struct blobmsg_policy emoji_policy[__EMOJI_MAX] = {
132	    [EMOJI_NAME] = { .name = "name", .type = BLOBMSG_TYPE_STRING },
133	    [EMOJI_ID]   = { .name = "id",   .type = BLOBMSG_TYPE_INT32 },
134	};
135	
136	static int m_set_emoji(struct ubus_context *ctx, struct ubus_object *obj,
137	                       struct ubus_request_data *req, const char *method,
138	                       struct blob_attr *msg)
139	{
140	    struct blob_attr *tb[__EMOJI_MAX];
141	    blobmsg_parse(emoji_policy, __EMOJI_MAX, tb, blob_data(msg), blob_len(msg));
142	
143	    /* 无视当前是否空闲/是否在屏保中，立即全屏循环播放该表情；触屏退出后
144	     * 下次空闲屏保仍恢复默认（一次性）。文件不存在则 ok=false。
145	     * 门控：全双工语音对话进行中(talking)拒绝表情播放，避免打断对话画面。 */
146	    if (doubao_voice_is_talking()) {
147	        blob_buf_init(&s_b, 0);
148	        blobmsg_add_u8(&s_b, "ok", 0);
149	        blobmsg_add_string(&s_b, "reason", "busy");
150	        ubus_send_reply(ctx, req, s_b.head);
151	        return 0;
152	    }
153	
154	    bool ok;
155	    if (tb[EMOJI_NAME])
156	        ok = screensaver_play_name(s_app, blobmsg_get_string(tb[EMOJI_NAME]));
157	    else if (tb[EMOJI_ID])
158	        ok = screensaver_play(s_app, blobmsg_get_u32(tb[EMOJI_ID]));
159	    else
160	        return UBUS_STATUS_INVALID_ARGUMENT;
161	
162	    blob_buf_init(&s_b, 0);
163	    blobmsg_add_u8(&s_b, "ok", ok);
164	    ubus_send_reply(ctx, req, s_b.head);
165	    return 0;
166	}
