168	/* ---------- sleep_show（睡眠报告页，sleepd 守护进程推送） ----------
169	 * 字段全部可缺省：数值字段接受 int 或 double（blobmsg_json 把带小数的解析成
170	 * DOUBLE、整数解析成 INTxx，故策略用 UNSPEC 再自行转换）；total 缺省按四项
171	 * score 加总；label/max/rating/date/summary 缺省给默认值（date 缺省用系统
172	 * 当前日期）。收到后切到睡眠报告页显示，60s 自动回主页，点击可提前返回。 */
173	
174	enum { SLP_TOTAL, SLP_RATING, SLP_DATE, SLP_SUMMARY,
175	       SLP_OFFBED, SLP_DURATION, SLP_TURNOVER, SLP_MICRO, __SLP_MAX };
176	static const struct blobmsg_policy sleep_policy[__SLP_MAX] = {
177	    [SLP_TOTAL]    = { .name = "total",    .type = BLOBMSG_TYPE_UNSPEC },
178	    [SLP_RATING]   = { .name = "rating",   .type = BLOBMSG_TYPE_STRING },
179	    [SLP_DATE]     = { .name = "date",     .type = BLOBMSG_TYPE_STRING },
180	    [SLP_SUMMARY]  = { .name = "summary",  .type = BLOBMSG_TYPE_STRING },
181	    [SLP_OFFBED]   = { .name = "offbed",   .type = BLOBMSG_TYPE_TABLE },
182	    [SLP_DURATION] = { .name = "duration", .type = BLOBMSG_TYPE_TABLE },
183	    [SLP_TURNOVER] = { .name = "turnover", .type = BLOBMSG_TYPE_TABLE },
184	    [SLP_MICRO]    = { .name = "micro",    .type = BLOBMSG_TYPE_TABLE },
185	};
186	
187	enum { DIM_SCORE, DIM_MAX, DIM_COUNT, DIM_LABEL, __DIM_MAX };
188	static const struct blobmsg_policy dim_policy[__DIM_MAX] = {
189	    [DIM_SCORE] = { .name = "score", .type = BLOBMSG_TYPE_UNSPEC },
190	    [DIM_MAX]   = { .name = "max",   .type = BLOBMSG_TYPE_UNSPEC },
191	    [DIM_COUNT] = { .name = "count", .type = BLOBMSG_TYPE_UNSPEC },
192	    [DIM_LABEL] = { .name = "label", .type = BLOBMSG_TYPE_STRING },
193	};
194	
195	/* 维度默认值（与评分权重一致）：下床 30 / 时长 30 / 翻身 20 / 微动 20 */
196	static const struct { const char *label; double max; } slp_dim_dflt[SLEEP_DIM_COUNT] = {
197	    { "下床次数", 30 }, { "睡眠时长", 30 }, { "翻身次数", 20 }, { "微动次数", 20 },
198	};
199	
200	/* 数值字段统一转 double：接受 DOUBLE 与各种整型，其他类型/缺失给默认值 */
201	static double attr_num(struct blob_attr *a, double dflt)
202	{
203	    if (!a)
204	        return dflt;
205	    switch (blobmsg_type(a)) {
206	        case BLOBMSG_TYPE_DOUBLE: return blobmsg_get_double(a);
207	        case BLOBMSG_TYPE_INT64:  return (double)blobmsg_get_u64(a);
208	        case BLOBMSG_TYPE_INT32:  return (double)blobmsg_get_u32(a);
209	        case BLOBMSG_TYPE_INT16:  return (double)blobmsg_get_u16(a);
210	        case BLOBMSG_TYPE_INT8:   return (double)blobmsg_get_u8(a);
211	        default:                  return dflt;
212	    }
213	}
214	
215	static void slp_parse_dim(struct blob_attr *tbl, sleep_dim_t *d,
216	                          const char *dflt_label, double dflt_max)
217	{
218	    d->score = 0;
219	    d->max   = dflt_max;
220	    d->count = 0;
221	    snprintf(d->label, sizeof(d->label), "%s", dflt_label);
222	
223	    if (!tbl)
224	        return;
225	    struct blob_attr *tb[__DIM_MAX];
226	    blobmsg_parse(dim_policy, __DIM_MAX, tb, blobmsg_data(tbl),
227	                  blobmsg_data_len(tbl));
228	    d->score = attr_num(tb[DIM_SCORE], 0);
229	    d->max   = attr_num(tb[DIM_MAX], dflt_max);
230	    d->count = attr_num(tb[DIM_COUNT], 0);
231	    if (tb[DIM_LABEL])
232	        snprintf(d->label, sizeof(d->label), "%s",
233	                 blobmsg_get_string(tb[DIM_LABEL]));
234	}
235	
236	static int m_sleep_show(struct ubus_context *ctx, struct ubus_object *obj,
237	                        struct ubus_request_data *req, const char *method,
238	                        struct blob_attr *msg)
239	{
240	    struct blob_attr *tb[__SLP_MAX];
241	    blobmsg_parse(sleep_policy, __SLP_MAX, tb, blob_data(msg), blob_len(msg));
242	
243	    sleep_report_t r;
244	    memset(&r, 0, sizeof(r));
245	
246	    slp_parse_dim(tb[SLP_OFFBED],   &r.dim[0],
247	                  slp_dim_dflt[0].label, slp_dim_dflt[0].max);
248	    slp_parse_dim(tb[SLP_DURATION], &r.dim[1],
249	                  slp_dim_dflt[1].label, slp_dim_dflt[1].max);
250	    slp_parse_dim(tb[SLP_TURNOVER], &r.dim[2],
251	                  slp_dim_dflt[2].label, slp_dim_dflt[2].max);
252	    slp_parse_dim(tb[SLP_MICRO],    &r.dim[3],
253	                  slp_dim_dflt[3].label, slp_dim_dflt[3].max);
254	
255	    /* total 缺省按四项 score 加总 */
256	    if (tb[SLP_TOTAL]) {
257	        r.total = attr_num(tb[SLP_TOTAL], 0);
258	    } else {
259	        for (int i = 0; i < SLEEP_DIM_COUNT; i++)
260	            r.total += r.dim[i].score;
261	    }
262	
263	    if (tb[SLP_RATING])
264	        snprintf(r.rating, sizeof(r.rating), "%s",
265	                 blobmsg_get_string(tb[SLP_RATING]));
266	    else
267	        snprintf(r.rating, sizeof(r.rating), "%s", "—");
268	
269	    if (tb[SLP_DATE])
270	        snprintf(r.date, sizeof(r.date), "%s", blobmsg_get_string(tb[SLP_DATE]));
271	    else
272	        sysinfo_get_date(r.date, sizeof(r.date));
273	
274	    if (tb[SLP_SUMMARY])
275	        snprintf(r.summary, sizeof(r.summary), "%s",
276	                 blobmsg_get_string(tb[SLP_SUMMARY]));
277	
278	    /* 屏保/轮播在前台时先退出，再展示报告页（露出的是报告 overlay） */
279	    if (screensaver_active(s_app))
280	        screensaver_stop(s_app);
281	    sleep_report_show(s_app, &r);
282	
283	    blob_buf_init(&s_b, 0);
284	    blobmsg_add_u8(&s_b, "ok", 1);
285	    ubus_send_reply(ctx, req, s_b.head);
286	    return 0;
287	}
