289	/* ---------- set_claude_status（Claude Code 状态） ----------
290	 * state: idle | thinking | executing | default；default 恢复普通轮播。 */
291	enum { CLAUDE_STATE, __CLAUDE_MAX };
292	static const struct blobmsg_policy claude_policy[__CLAUDE_MAX] = {
293	    [CLAUDE_STATE] = { .name = "state", .type = BLOBMSG_TYPE_STRING },
294	};
295	
296	static int m_set_claude_status(struct ubus_context *ctx, struct ubus_object *obj,
297	                               struct ubus_request_data *req, const char *method,
298	                               struct blob_attr *msg)
299	{
300	    struct blob_attr *tb[__CLAUDE_MAX];
301	    blobmsg_parse(claude_policy, __CLAUDE_MAX, tb, blob_data(msg), blob_len(msg));
302	    if (!tb[CLAUDE_STATE])
303	        return UBUS_STATUS_INVALID_ARGUMENT;
304	
305	    const char *state = blobmsg_get_string(tb[CLAUDE_STATE]);
306	    bool ok = screensaver_set_claude_status(s_app, state);
307	    blob_buf_init(&s_b, 0);
308	    blobmsg_add_u8(&s_b, "ok", ok);
309	    if (!ok)
310	        blobmsg_add_string(&s_b, "reason", "invalid_state");
311	    ubus_send_reply(ctx, req, s_b.head);
312	    return 0;
313	}
