357	/* ---------- ask_text（文字问答：传文字 → 豆包回文字+TTS语音） ---------- */
358	enum { ASK_TEXT, __ASK_MAX };
359	static const struct blobmsg_policy ask_policy[__ASK_MAX] = {
360	    [ASK_TEXT] = { .name = "text", .type = BLOBMSG_TYPE_STRING },
361	};
362	
363	static int m_ask_text(struct ubus_context *ctx, struct ubus_object *obj,
364	                      struct ubus_request_data *req, const char *method,
365	                      struct blob_attr *msg)
366	{
367	    struct blob_attr *tb[__ASK_MAX];
368	    blobmsg_parse(ask_policy, __ASK_MAX, tb, blob_data(msg), blob_len(msg));
369	    if (!tb[ASK_TEXT])
370	        return UBUS_STATUS_INVALID_ARGUMENT;
371	
372	    int rc = doubao_voice_ask_text(blobmsg_get_string(tb[ASK_TEXT]));
373	
374	    /* 语音优先：全双工对话中或上一条文字回复未播完 → busy，不打断语音。 */
375	    const char *reason = NULL;
376	    switch (rc) {
377	        case 0:        reason = NULL;            break;
378	        case -EBUSY:   reason = "busy";          break;  /* 语音对话中/上条未完 */
379	        case -EAGAIN:  reason = "not_ready";     break;  /* 连接未就绪 */
380	        case -ENOKEY:  reason = "unconfigured";  break;
381	        case -EINVAL:  reason = "empty";         break;
382	        default:       reason = "error";         break;
383	    }
384	
385	    blob_buf_init(&s_b, 0);
386	    blobmsg_add_u8(&s_b, "ok", rc == 0);
387	    if (reason)
388	        blobmsg_add_string(&s_b, "reason", reason);
389	    ubus_send_reply(ctx, req, s_b.head);
390	    return 0;
391	}
