393	/* ---------- start_talk / stop_talk（全双工语音对话开始/挂断） ----------
394	 * 等价于轮播页右下角热区的对话开关，供程序化控制。连接由 worker 常驻维护：
395	 * start 只切换到上传真实麦克风，stop 立即静音挂断并丢弃本轮残留 TTS，两者
396	 * 都不重建/断开连接（零等待），也都不切换界面——对话在后台运行，界面始终
397	 * 停留轮播首页。回复 {"ok":bool[,"reason":str]}。talking 期间 set_emoji/
398	 * ask_text 会被门控拒绝(reason="busy")。 */
399	
400	static int m_start_talk(struct ubus_context *ctx, struct ubus_object *obj,
401	                        struct ubus_request_data *req, const char *method,
402	                        struct blob_attr *msg)
403	{
404	    /* 对话在 worker 线程后台运行，界面停留轮播首页(不切对话桌面)，故此处
405	     * 不动屏保，只切换 talking。等价轮播页点右下角热区开始对话。 */
406	    int rc = doubao_voice_start();
407	    const char *reason = NULL;
408	    if (rc == -ENOKEY)      reason = "unconfigured";
409	    else if (rc != 0)       reason = "error";
410	
411	    blob_buf_init(&s_b, 0);
412	    blobmsg_add_u8(&s_b, "ok", rc == 0);
413	    if (reason)
414	        blobmsg_add_string(&s_b, "reason", reason);
415	    ubus_send_reply(ctx, req, s_b.head);
416	    return 0;
417	}
