477	        case 0:        reason = NULL;            break;
478	        case -EBUSY:   reason = "busy";          break;  /* 语音对话中/上条未完 */
479	        case -EAGAIN:  reason = "not_ready";     break;  /* 连接未就绪 */
480	        case -ENOKEY:  reason = "unconfigured";  break;
481	        case -EINVAL:  reason = "empty";         break;
482	        default:       reason = "error";         break;
483	    }
484	
485	    blob_buf_init(&s_b, 0);
486	    blobmsg_add_u8(&s_b, "ok", rc == 0);
487	    if (reason)
488	        blobmsg_add_string(&s_b, "reason", reason);
489	    ubus_send_reply(ctx, req, s_b.head);
490	    return 0;
491	}
