602	/* 供语音意图模块调用 sleepd 的 "sleep" 对象方法。
603	 * method: "start"/"stop"/"show_report"/"get_status"；json 为可选参数体。
604	 * 异步 fire-and-forget：blob 用静态 buf（请求挂起期间必须存活）。 */
605	int ubus_call_sleep(const char *method, const char *json)
606	{
607	    static struct blob_buf b;
608	    uint32_t id;
609	
610	    if (!s_ctx)
611	        return -1;
612	    if (ubus_lookup_id(s_ctx, "sleep", &id) != 0) {
613	        fprintf(stderr, "[ubus] sleep 对象不存在（sleepd 未运行？）\n");
614	        return -2;
615	    }
616	    blob_buf_init(&b, 0);
617	    if (json)
618	        blobmsg_add_json_from_string(&b, json);
619	    return ubus_invoke(s_ctx, id, method, b.head, NULL, NULL, 3000);
620	}
