1	/*
2	 * screensaver.c —— 常驻轮播首页 + 表情主动展示：全屏播放动态 WebP 表情。
3	 *
4	 * 触发逻辑：
5	 *   - 轮播首页(常驻默认视图)：应用启动即进入，循环轮播 [FIRST,LAST] 号表情。
6	 *     视图与对话状态解耦——对话开/关(talking)只由 ubus start_talk/stop_talk
7	 *     控制、在 worker 线程后台运行；右下角热区只切视图不动对话：
8	 *       · 轮播视图点右下角 → ss_exit 隐藏 overlay，露出对话模式页(ui->scr)，
9	 *         立刻可见当前对话的 TTS 文字实时刷新；
10	 *       · 对话模式页点右下角 → screensaver_show 显示 overlay，切回轮播视图。
11	 *     两视图唯一区别：轮播视图看不到文字，对话模式页看得到文字。无论对话是否
12	 *     进行都能自由切换。轮播视图其余区域无视触屏，永不因触摸退出。
13	 *   - ubus 主动展示：其他应用调 desktop.set_emoji {"id":N} → 立即全屏循环播放
14	 *     N 号表情，无视当前状态；一次性——触屏或 SS_AUTO_EXIT_MS 到期退回。
15	 *     (talking 期间该请求在 ubus 层被拒绝，不打断对话。)
16	 *   - overlay 位于 lv_layer_top 且可点击不透明，拦截触摸不穿透到下方按钮
17	 *     （一次性表情展示时首次触摸只退展示，不误触下方录音/会话按钮）。
18	 *
19	 * WebP 解码：LVGL v8.3 无内置 WebP 支持，用设备自带 libwebp/libwebpdemux 的
20	 * WebPAnimDecoder 动画 API。以 MODE_BGRA 直出，与 LVGL 32bit BGRA 内存序一致，
21	 * 配 LV_IMG_CF_TRUE_COLOR_ALPHA 直接喂 canvas，无需 R/B 交换。
22	 *
23	 * 内存策略：懒建单 decoder，任意时刻只驻留 1 份文件缓冲(≤211KB)+1 个 decoder。
24	 * 单文件循环用 WebPAnimDecoderReset 重头播（不重读文件、不重建 decoder）；
25	 * 切换表情才重建。GetNext 返回的画布下次调用即失效，故每帧 memcpy 到自有常驻
26	 * 缓冲 canvas_buf 再交给 canvas。单线程 uloop 下帧推进（timer 回调）与渲染
27	 * （lv_timer_handler）串行执行，单缓冲安全，无需加锁/双缓冲。
28	 *
29	 * 健壮性：文件读/解码失败即静默不进（或维持原状）；默认表情缺失则 ready=false
30	 * 静默禁用，主界面不受影响。
31	 */
32	#include "app.h"
33	#include "doubao/voice.h"
34	#include "music.h"
35	#include "lvgl/lvgl.h"
36	
