43	/* 轮播为常驻首页，进入/退出由会话状态驱动(见 screensaver_tick)，不再依赖
44	 * 空闲计时；原 SS_IDLE_MS 空闲阈值已废弃移除。 */
45	/* 表情尺寸不再固定：数字表情 480x198、命名表情 1920x792 等混用。canvas 缓冲
46	 * 按最大尺寸一次性分配，每个文件按其实际宽高渲染并重新居中。 */
47	#define SS_MAX_W        1920
48	#define SS_MAX_H        792
49	#define SS_MAX_BYTES    (SS_MAX_W * SS_MAX_H * 4)   /* 6082560 字节，BGRA 上限 */
50	#define SS_RES_DIR      "/usr/share/desktop-app/emoji"
51	#define SS_MIN_DUR      20                  /* 单帧最短显示时长(ms)，防 0 时长忙转 */
