53	#define SS_AUTO_EXIT_MS 10000               /* ubus 主动展示的自动退出时长(ms) */
54	#define SS_CAROUSEL_FIRST 1                 /* 空闲屏保轮播编号区间 [FIRST,LAST] */
55	#define SS_CAROUSEL_LAST  13                /* 缺失的编号(如 10)自动跳过 */
56	#define SS_HOTSPOT_SZ     260               /* 右下角进入对话的触摸热区边长(px) */
57	#define SS_TALK_LISTEN    "listen.webp"     /* 全双工对话·收音/等待时的表情 */
58	#define SS_TALK_SPEAK     "speak.webp"      /* 全双工对话·AI 说话(TTS)时的表情 */
