106	/* ---- 读取整个文件到内存 ---- */
107	static uint8_t *read_file(const char *path, size_t *out_size)
108	{
109	    FILE *fp = fopen(path, "rb");
110	    if (!fp)
111	        return NULL;
112	    fseek(fp, 0, SEEK_END);
113	    long sz = ftell(fp);
114	    fseek(fp, 0, SEEK_SET);
115	    if (sz <= 0) {
116	        fclose(fp);
117	        return NULL;
118	    }
119	    uint8_t *buf = malloc((size_t)sz);
120	    if (!buf) {
121	        fclose(fp);
122	        return NULL;
123	    }
124	    size_t rd = fread(buf, 1, (size_t)sz, fp);
125	    fclose(fp);
126	    if (rd != (size_t)sz) {
127	        free(buf);
128	        return NULL;
129	    }
130	    *out_size = (size_t)sz;
131	    return buf;
132	}
