134	/* ---- 关闭当前 decoder，释放文件缓冲 ---- */
135	static void ss_close_decoder(void)
136	{
137	    if (s.dec) {
138	        WebPAnimDecoderDelete(s.dec);
139	        s.dec = NULL;
140	    }
141	    if (s.file_data) {
142	        free(s.file_data);
143	        s.file_data = NULL;
144	    }
145	    s.file_size = 0;
146	    s.frame_count = 0;
147	    s.prev_ts = 0;
148	}
