150	/* ---- 打开 s.play_file 指向的文件并建 decoder。成功返回 true ---- */
151	static bool ss_open_decoder(app_ctx_t *app)
152	{
153	    (void)app;
154	    char path[256];
155	    snprintf(path, sizeof(path), "%s/%s", SS_RES_DIR, s.play_file);
156	
157	    size_t size = 0;
158	    uint8_t *data = read_file(path, &size);
159	    if (!data) {
160	        fprintf(stderr, "[ss] 读取失败 %s\n", path);
161	        return false;
162	    }
163	
164	    WebPData wd = { .bytes = data, .size = size };
165	    WebPAnimDecoderOptions opt;
166	    WebPAnimDecoderOptionsInit(&opt);
167	    opt.color_mode = MODE_BGRA;         /* 与 LVGL 32bit BGRA 内存序一致 */
168	    opt.use_threads = 0;
169	
170	    WebPAnimDecoder *dec = WebPAnimDecoderNew(&wd, &opt);
171	    if (!dec) {
172	        fprintf(stderr, "[ss] 解码器创建失败 %s\n", path);
173	        free(data);
174	        return false;
175	    }
176	
177	    WebPAnimInfo info;
178	    if (!WebPAnimDecoderGetInfo(dec, &info) ||
179	        (int)info.canvas_width > SS_MAX_W || (int)info.canvas_height > SS_MAX_H ||
180	        info.canvas_width == 0 || info.canvas_height == 0) {
181	        fprintf(stderr, "[ss] 尺寸不支持 %s (%ux%u，上限 %dx%d)\n",
182	                path, info.canvas_width, info.canvas_height, SS_MAX_W, SS_MAX_H);
183	        WebPAnimDecoderDelete(dec);
184	        free(data);
185	        return false;
186	    }
187	
188	    s.dec         = dec;
189	    s.file_data   = data;
190	    s.file_size   = size;
191	    s.cur_w       = (int)info.canvas_width;
192	    s.cur_h       = (int)info.canvas_height;
193	    s.frame_count = (int)info.frame_count;
194	    s.prev_ts     = 0;
195	    return true;
196	}
