198	/* ---- 帧推进定时器回调 ---- */
199	static void ss_frame_cb(lv_timer_t *t)
200	{
201	    app_ctx_t *app = t->user_data;
202	
203	    if (!s.dec) {
204	        ss_exit(app);
205	        return;
206	    }
207	    if (!WebPAnimDecoderHasMoreFrames(s.dec)) {
208	        /* 对话态锁定(listen/speak)：只重头循环当前表情，不切数字编号。 */
209	        if (s.carousel && !s.talk_file[0]) {
210	            /* 轮播模式：当前表情播完一轮 → 切下一个编号（一直轮播不退出） */
211	            if (ss_carousel_advance(app))
212	                return;             /* 已切到下一个文件，帧由新 timer 周期推进 */
213	            /* 切换失败(极端情况)：退化为重头循环当前文件 */
214	        }
215	        /* 单文件循环：重置回首帧重头播（不重读文件、不重建 decoder） */
216	        WebPAnimDecoderReset(s.dec);
217	        s.prev_ts = 0;
218	    }
219	
220	    uint8_t *frame = NULL;
221	    int ts = 0;
222	    if (!WebPAnimDecoderGetNext(s.dec, &frame, &ts) || !frame) {
223	        ss_exit(app);           /* 解码出错，兜底退出 */
224	        return;
225	    }
226	
227	    /* GetNext 的画布下次调用即失效，必须拷贝到自有缓冲再交给 canvas。
