229	     * 再 center 保证不同尺寸表情都居中。 */
230	    memcpy(s.canvas_buf, frame, (size_t)s.cur_w * s.cur_h * 4);
231	    lv_canvas_set_buffer(s.canvas, s.canvas_buf, s.cur_w, s.cur_h,
232	                         LV_IMG_CF_TRUE_COLOR_ALPHA);
233	    lv_obj_center(s.canvas);
234	
235	    int dur = ts - s.prev_ts;
236	    if (dur < SS_MIN_DUR)
