231	void demo_advanced_control(void)
232	{
233	    printf("\n=== LED Advanced Control Demo ===\n");
234	    led_controller_init();
235	    printf("Setting custom color and turning ON...\n");
236	    led_set_rgb(255, 165, 0);
237	    led_on();
238	    sleep(2);
239	    for (int i = 100; i >= 0; i -= 20) {
240	        led_set_brightness(i);
241	        printf("Brightness: %d%%\n", i);
242	        sleep(1);
243	    }
244	    for (int i = 0; i <= 100; i += 20) {
245	        led_set_brightness(i);
246	        printf("Brightness: %d%%\n", i);
247	        sleep(1);
248	    }
