253	/*===========================================================================
254	 * Internal: apply brightness-adjusted color to hardware
255	 *===========================================================================*/
256	static led_error_t apply_led_settings(void)
257	{
258	    if (!g_initialized)    return LED_ERROR_NOT_RUNNING;
259	    if (!g_led_status.is_running) return LED_SUCCESS;
260	
261	    uint32_t actual_color = g_led_status.color;
262	    if (g_led_status.brightness < 100) {
263	        uint8_t r, g, b;
264	        led_hex_to_rgb(actual_color, &r, &g, &b);
265	        r = (r * g_led_status.brightness) / 100;
266	        g = (g * g_led_status.brightness) / 100;
267	        b = (b * g_led_status.brightness) / 100;
268	        actual_color = led_rgb_to_hex(r, g, b);
269	    }
270	
271	#ifdef CONFIG_LED_RGB_WS2812
272	    if (ctrl_ws2812(actual_color) != 0) {
273	        _info("Error setting LED color\n");
274	        return LED_ERROR_HARDWARE;
275	    }
276	#else
277	    if (sunxi_set_led_brightness(0, actual_color) != 0) {
278	        _info("Error setting LED color\n");
279	        return LED_ERROR_HARDWARE;
280	    }
281	#endif
282	    return LED_SUCCESS;
283	}
