1	/****************************************************************************
2	 * app/home_scense/ui_status.c
3	 * Claude Code status receiver — reads FIFO and controls LED state.
4	 *
5	 * LED mapping:
6	 *   processing → green blink (500ms toggle)
7	 *   waiting    → red static
8	 ****************************************************************************/
9	
10	#include "ui_status.h"
11	#include "main.h"
12	
13	#include <fcntl.h>
14	#include <stdio.h>
15	#include <string.h>
16	#include <sys/stat.h>
17	#include <unistd.h>
18	#include <debug.h>
19	
20	#define FIFO_PATH         "/tmp/claude_status.pipe"
21	#define BLINK_TOGGLE_MS   500
22	#define POLL_INTERVAL_MS  100
23	
24	/* Hardware write — apply brightness */
25	static int led_write(uint32_t color)
26	{
27	    if (g_led_brightness < 100) {
28	        uint8_t r = (color >> 16) & 0xFF;
29	        uint8_t g = (color >> 8)  & 0xFF;
30	        uint8_t b =  color        & 0xFF;
31	        r = (r * g_led_brightness) / 100;
32	        g = (g * g_led_brightness) / 100;
33	        b = (b * g_led_brightness) / 100;
34	        color = (r << 16) | (g << 8) | b;
35	    }
36	    int fd = open("/dev/leds0", O_RDWR);
37	    if (fd < 0) return -1;
38	    int ret = write(fd, &color, sizeof(color));
39	    close(fd);
40	    return (sizeof(color) == ret) ? 0 : -1;
41	}
42	
43	/* Internal state */
44	static int              g_fifo_fd  = -1;
45	static claude_status_t  g_current  = CLAUDE_STATUS_NONE;
46	static int              g_tick     = 0;
47	static bool             g_on       = false;
48	
49	/*-----------------------------------------------------------------------
50	 * State machine
51	 *---------------------------------------------------------------------*/
52	static claude_status_t parse_state(const char *s)
53	{
54	    if (strcmp(s, "processing") == 0) return CLAUDE_STATUS_PROCESSING;
55	    if (strcmp(s, "completed")  == 0) return CLAUDE_STATUS_COMPLETED;
56	    if (strcmp(s, "waiting")    == 0) return CLAUDE_STATUS_WAITING;
57	    if (strcmp(s, "started")    == 0) return CLAUDE_STATUS_STARTED;
58	    if (strcmp(s, "ended")      == 0) return CLAUDE_STATUS_ENDED;
59	    return CLAUDE_STATUS_NONE;
60	}
61	
62	static const char *extract_state(const char *json, char *buf, size_t n)
63	{
64	    const char *key = "\"state\":\"";
65	    const char *s = strstr(json, key);
66	    if (!s) { key = "\"state\": \""; s = strstr(json, key); }
67	    if (!s) return NULL;
68	    s += strlen(key);
69	    const char *e = strchr(s, '"');
70	    if (!e) return NULL;
71	    size_t len = e - s;
72	    if (len >= n) return NULL;
73	    memcpy(buf, s, len); buf[len] = '\0';
74	    return buf;
75	}
76	
77	static void apply_state(claude_status_t st)
78	{
79	    g_tick = 0;
80	    g_on   = false;
81	
82	    if (st == CLAUDE_STATUS_STARTED || st == CLAUDE_STATUS_ENDED) {
83	        led_write(0x000000);
84	        return;
85	    }
86	    if (!g_led_is_on) return;
87	
88	    switch (st) {
89	    case CLAUDE_STATUS_PROCESSING: led_write(0x00FF00); g_on = true; break;  /* green blink */
90	    case CLAUDE_STATUS_COMPLETED:  led_write(0x00FF00); break;               /* legacy */
91	    case CLAUDE_STATUS_WAITING:    led_write(0xFF0000); break;               /* red */
92	    default: break;
93	    }
94	}
95	
96	/*-----------------------------------------------------------------------
97	 * Public
98	 *---------------------------------------------------------------------*/
99	
100	void claude_status_init(void)
101	{
102	    struct stat st;
103	    if (stat(FIFO_PATH, &st) != 0) mkfifo(FIFO_PATH, 0666);
104	
105	    g_fifo_fd = open(FIFO_PATH, O_RDONLY | O_NONBLOCK);
106	    if (g_fifo_fd >= 0) {
107	        _info("ui_status: FIFO opened\n");
108	    }
109	    g_current = CLAUDE_STATUS_NONE;
110	}
111	
112	void claude_status_deinit(void)
113	{
114	    if (g_fifo_fd >= 0) { close(g_fifo_fd); g_fifo_fd = -1; }
115	    led_write(0x000000);
116	    g_current = CLAUDE_STATUS_NONE;
117	}
118	
119	void claude_status_poll(lv_timer_t *timer)
120	{
121	    (void)timer;
122	
123	    /* 1. Read FIFO first — must process state changes before blinking */
124	    if (g_fifo_fd < 0) {
125	        g_fifo_fd = open(FIFO_PATH, O_RDONLY | O_NONBLOCK);
126	    }
127	
128	    if (g_fifo_fd >= 0) {
129	        char buf[256];
130	        ssize_t n = read(g_fifo_fd, buf, sizeof(buf) - 1);
131	        if (n == 0) { close(g_fifo_fd); g_fifo_fd = open(FIFO_PATH, O_RDONLY | O_NONBLOCK); }
132	        else if (n > 0) {
133	            buf[n] = '\0';
134	            char *line = buf;
135	            for (char *p = buf; *p; p++) {
136	                if (*p == '\n' || *p == '\r') {
137	                    *p = '\0';
138	                    char st_buf[32];
139	                    const char *st = extract_state(line, st_buf, sizeof(st_buf));
140	                    claude_status_t new_st = st ? parse_state(st) : CLAUDE_STATUS_NONE;
141	                    if (new_st != CLAUDE_STATUS_NONE && new_st != g_current) {
142	                        g_current = new_st;
143	                        apply_state(new_st);
144	                        _info("ui_status: -> %s\n", st);
145	                    }
146	                    line = p + 1;
147	                }
148	            }
149	        }
150	    }
151	
152	    /* 2. Blink — only after state has been updated above */
153	    if (g_current == CLAUDE_STATUS_PROCESSING) {
154	        g_tick += POLL_INTERVAL_MS;
155	        if (g_tick >= BLINK_TOGGLE_MS) {
156	            g_tick -= BLINK_TOGGLE_MS;
157	            if (g_led_is_on) {
158	                g_on = !g_on;
159	                led_write(g_on ? 0x00FF00 : 0x000000);
160	            }
161	        }
162	    }
163	}
164	
165	claude_status_t claude_status_get(void) { return g_current; }
166	bool claude_status_is_active(void)      { return true; }
167	
168	void claude_status_reapply(void)
169	{
170	    if (!g_led_is_on || g_current == CLAUDE_STATUS_NONE) return;
171	    apply_state(g_current);
172	}
