1	/****************************************************************************
2	 * ui_emoji_idle.c — sequential multi-emoji keyframe animation.
3	 * Blob embedded via .S, zero malloc, zero file I/O.
4	 * Plays emoji 0→1→...→12 in order, loops back to 0.
5	 ****************************************************************************/
6	#include "ui_emoji_idle.h"
7	#include "main.h"
8	#include "emoji_blob.h"
9	#include <string.h>
10	
11	typedef struct {
12	    lv_obj_t   *overlay;
13	    lv_obj_t   *img;
14	    lv_timer_t *timer;
15	    int         emoji_idx;     /* 0..EMOJI_COUNT-1 */
16	    int         keyframe;      /* 0..EMOJI_MAX_KEYFRAMES-1 */
17	    emoji_idle_exit_cb_t on_exit;
18	} emoji_idle_t;
19	
20	static emoji_idle_t   g_idle;
21	static lv_image_dsc_t g_dsc;
22	static int            g_next_emoji;  /* round-robin cursor */
23	
24	/*-----------------------------------------------------------------------
25	 * Timer: advance keyframe; wrap to next emoji at end of current one.
26	 *---------------------------------------------------------------------*/
27	static void anim_cb(lv_timer_t *t)
28	{
29	    (void)t;
30	
31	    g_idle.keyframe++;
32	    if (g_idle.keyframe >= EMOJI_MAX_KEYFRAMES) {
33	        g_idle.emoji_idx = g_next_emoji;
34	        g_idle.keyframe  = 0;
35	        g_next_emoji     = (g_idle.emoji_idx + 1) % EMOJI_COUNT;
36	    }
37	
38	    const unsigned char *frame = emoji_blob_data +
39	        ((unsigned)g_idle.emoji_idx * EMOJI_MAX_KEYFRAMES +
40	         (unsigned)g_idle.keyframe) * EMOJI_FRAME_BYTES;
41	    g_dsc.data = (uint8_t *)frame;
42	    lv_image_set_src(g_idle.img, &g_dsc);
43	}
44	
45	/*-----------------------------------------------------------------------
46	 * Tap dismiss
47	 *---------------------------------------------------------------------*/
48	static void click_cb(lv_event_t *e)
49	{
50	    (void)e;
51	    if (g_idle.timer)   { lv_timer_del(g_idle.timer); }
52	    if (g_idle.overlay) { lv_obj_del(g_idle.overlay); }
53	    if (g_idle.on_exit) g_idle.on_exit();
54	    memset(&g_idle, 0, sizeof(g_idle));
55	}
56	
57	/*-----------------------------------------------------------------------
58	 * Public
59	 *---------------------------------------------------------------------*/
60	lv_obj_t *emoji_idle_create(lv_obj_t *parent, emoji_idle_exit_cb_t on_exit)
61	{
62	    memset(&g_idle, 0, sizeof(g_idle));
63	
64	    int idx = g_next_emoji;
65	    g_idle.emoji_idx = idx;
66	    g_idle.keyframe  = 0;
67	    g_idle.on_exit   = on_exit;
68	    g_next_emoji     = (idx + 1) % EMOJI_COUNT;
69	
70	    /* First frame of the chosen emoji */
71	    const unsigned char *first = emoji_blob_data +
72	        ((unsigned)idx * EMOJI_MAX_KEYFRAMES) * EMOJI_FRAME_BYTES;
73	
74	    memset(&g_dsc, 0, sizeof(g_dsc));
75	    g_dsc.header.magic  = LV_IMAGE_HEADER_MAGIC;
76	    g_dsc.header.cf     = LV_COLOR_FORMAT_RGB565;
77	    g_dsc.header.w      = EMOJI_FRAME_W;
78	    g_dsc.header.h      = EMOJI_FRAME_H;
79	    g_dsc.header.stride = EMOJI_FRAME_W * 2;
80	    g_dsc.data          = (uint8_t *)first;
81	    g_dsc.data_size     = EMOJI_FRAME_BYTES;
82	
83	    /* Overlay */
84	    g_idle.overlay = lv_obj_create(parent);
85	    lv_obj_set_size(g_idle.overlay, SCREEN_WIDTH, SCREEN_HEIGHT);
86	    lv_obj_set_pos(g_idle.overlay, 0, 0);
87	    lv_obj_set_style_bg_color(g_idle.overlay, lv_color_black(), 0);
88	    lv_obj_set_style_bg_opa(g_idle.overlay, LV_OPA_COVER, 0);
89	    lv_obj_set_style_border_width(g_idle.overlay, 0, 0);
90	    lv_obj_set_style_radius(g_idle.overlay, 0, 0);
91	    lv_obj_set_style_pad_all(g_idle.overlay, 0, 0);
92	    lv_obj_set_scrollbar_mode(g_idle.overlay, LV_SCROLLBAR_MODE_OFF);
93	    lv_obj_clear_flag(g_idle.overlay, LV_OBJ_FLAG_SCROLLABLE);
94	    lv_obj_add_flag(g_idle.overlay, LV_OBJ_FLAG_CLICKABLE);
95	
96	    /* Image — centred */
97	    g_idle.img = lv_image_create(g_idle.overlay);
98	    lv_obj_set_size(g_idle.img, EMOJI_FRAME_W, EMOJI_FRAME_H);
99	    lv_obj_set_style_pad_all(g_idle.img, 0, 0);
100	    lv_obj_set_style_border_width(g_idle.img, 0, 0);
101	    lv_obj_align(g_idle.img, LV_ALIGN_CENTER, 0, 0);
102	    lv_image_set_src(g_idle.img, &g_dsc);
103	
104	    /* 150ms = ~6.7fps, smooth for 10-frame animation */
105	    g_idle.timer = lv_timer_create(anim_cb, 150, NULL);
106	    lv_timer_set_repeat_count(g_idle.timer, -1);
107	    lv_obj_add_event_cb(g_idle.overlay, click_cb, LV_EVENT_CLICKED, NULL);
108	
109	    return g_idle.overlay;
110	}
