#include "ui_claude_status.h"
#include "claude_assets.h"
#include "main.h"
#include "led_control.h"
#include <string.h>

static lv_obj_t *g_overlay;
static lv_obj_t *g_img;
static lv_obj_t *g_label;
static lv_timer_t *g_timer;
static const uint8_t *g_data;
static int g_frames;
static int g_frame;
static lv_image_dsc_t g_dsc;

static void frame_cb(lv_timer_t *t)
{
    (void)t;
    if (!g_img || !g_data || g_frames <= 0) return;
    g_frame = (g_frame + 1) % g_frames;
    g_dsc.data = (uint8_t *)(g_data + g_frame * CLAUDE_FRAME_BYTES);
    lv_image_set_src(g_img, &g_dsc);
}

void ui_claude_status_init(lv_obj_t *parent)
{
    g_overlay = lv_obj_create(parent);
    lv_obj_set_size(g_overlay, SCREEN_WIDTH, SCREEN_HEIGHT);
    lv_obj_set_pos(g_overlay, 0, 0);
    lv_obj_set_style_bg_color(g_overlay, lv_color_black(), 0);
    lv_obj_set_style_bg_opa(g_overlay, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(g_overlay, 0, 0);
    lv_obj_set_style_pad_all(g_overlay, 0, 0);
    lv_obj_clear_flag(g_overlay, LV_OBJ_FLAG_SCROLLABLE);
    g_img = lv_image_create(g_overlay);
    lv_obj_set_size(g_img, CLAUDE_FRAME_W, CLAUDE_FRAME_H);
    lv_obj_align(g_img, LV_ALIGN_TOP_MID, 0, 8);
    memset(&g_dsc, 0, sizeof(g_dsc));
    g_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
    g_dsc.header.cf = LV_COLOR_FORMAT_RGB565;
    g_dsc.header.w = CLAUDE_FRAME_W;
    g_dsc.header.h = CLAUDE_FRAME_H;
    g_dsc.header.stride = CLAUDE_FRAME_W * 2;
    g_dsc.data_size = CLAUDE_FRAME_BYTES;
    g_label = lv_label_create(g_overlay);
    lv_obj_set_style_text_font(g_label, g_misans_normal_16, 0);
    lv_obj_set_style_text_color(g_label, lv_color_white(), 0);
    lv_obj_align(g_label, LV_ALIGN_BOTTOM_MID, 0, -20);
    lv_obj_add_flag(g_overlay, LV_OBJ_FLAG_HIDDEN);
    g_timer = lv_timer_create(frame_cb, 150, NULL);
    lv_timer_pause(g_timer);
}

void ui_claude_status_set(const char *state)
{
    const char *text = NULL;
    if (!state) state = "default";
    if (strcmp(state, "idle") == 0) { g_data = claude_idle_data; g_frames = CLAUDE_IDLE_FRAMES; text = "休息中"; }
    else if (strcmp(state, "thinking") == 0) { g_data = claude_thinking_data; g_frames = CLAUDE_THINKING_FRAMES; text = "正在思考中"; }
    else if (strcmp(state, "executing") == 0) { g_data = claude_executing_data; g_frames = CLAUDE_EXECUTING_FRAMES; text = "正在工作中"; }
    if (!text) {
        lv_obj_add_flag(g_overlay, LV_OBJ_FLAG_HIDDEN);
        lv_timer_pause(g_timer);
        return;
    }
    g_frame = 0;
    g_dsc.data = (uint8_t *)g_data;
    lv_image_set_src(g_img, &g_dsc);
    lv_label_set_text(g_label, text);
    lv_obj_clear_flag(g_overlay, LV_OBJ_FLAG_HIDDEN);
    lv_timer_resume(g_timer);
}

void ui_claude_status_deinit(void)
{
    if (g_timer) lv_timer_del(g_timer);
    if (g_overlay) lv_obj_del(g_overlay);
    g_timer = NULL; g_overlay = NULL; g_img = NULL; g_label = NULL;
}

#include "claude_mqtt.h"
#include "ui_claude_status.h"
#include "led_control.h"
#include "main.h"
#include <mqtt.h>
#include <pthread.h>
#include <netdb.h>
#include <sys/socket.h>
#include <unistd.h>
#include <string.h>
#include <time.h>

#define BROKER "test.mosquitto.org"
#define PORT "1883"
#define TOPIC "hex-fight/claude-code/status/v1"
#define LEASE_SECONDS 20

static pthread_t g_thread;
static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
static volatile bool g_running;
static char g_state[16] = "default";
static char g_pending[16] = "default";
static bool g_changed;

struct mqtt_ctx { const char *host; const char *port; uint8_t sendbuf[2048]; uint8_t recvbuf[2048]; };

static int open_socket(void)
{
    struct addrinfo hints = {0}, *res, *p;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_family = AF_UNSPEC;
    if (getaddrinfo(BROKER, PORT, &hints, &res) != 0) return -1;
    int fd = -1;
    for (p = res; p; p = p->ai_next) {
        fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (fd >= 0 && connect(fd, p->ai_addr, p->ai_addrlen) == 0) break;
        if (fd >= 0) { close(fd); fd = -1; }
    }
    freeaddrinfo(res);
    return fd;
}

static void publish_cb(void **unused, struct mqtt_response_publish *p)
{
    char state[16];
    (void)unused;
    if (p->topic_name_size != sizeof(TOPIC) - 1 ||
        memcmp(p->topic_name, TOPIC, sizeof(TOPIC) - 1) != 0 ||
        p->application_message_size >= sizeof(state)) return;
    memcpy(state, p->application_message, p->application_message_size);
    state[p->application_message_size] = '\0';
    if (strcmp(state, "online") && strcmp(state, "offline") &&
        strcmp(state, "idle") && strcmp(state, "thinking") && strcmp(state, "executing")) return;
    pthread_mutex_lock(&g_lock);
    if (!strcmp(state, "online")) {
        if (!strcmp(g_state, "default")) strcpy(g_pending, "idle");
    } else if (!strcmp(state, "offline")) strcpy(g_pending, "default");
    else strcpy(g_pending, state);
    g_changed = true;
    pthread_mutex_unlock(&g_lock);
}

static void *mqtt_worker(void *arg)
{
    struct mqtt_ctx *ctx = arg;
    struct mqtt_client client;
    mqtt_init_reconnect(&client, NULL, NULL, publish_cb);
    while (g_running) {
        int fd = open_socket();
        if (fd < 0) { sleep(3); continue; }
        mqtt_reinit(&client, fd, ctx->sendbuf, sizeof(ctx->sendbuf), ctx->recvbuf, sizeof(ctx->recvbuf));
        mqtt_connect(&client, NULL, NULL, NULL, 0, NULL, NULL, MQTT_CONNECT_CLEAN_SESSION, 400);
        if (client.error == MQTT_OK) mqtt_subscribe(&client, TOPIC, 0);
        while (g_running && client.error == MQTT_OK) { mqtt_sync(&client); usleep(100000); }
        close(fd);
        sleep(2);
    }
    return NULL;
}

void claude_mqtt_init(void)
{
    static struct mqtt_ctx ctx;
    g_running = true;
    pthread_create(&g_thread, NULL, mqtt_worker, &ctx);
}

void claude_mqtt_poll(lv_timer_t *timer)
{
    static uint32_t lease;
    char state[16];
    (void)timer;
    pthread_mutex_lock(&g_lock);
    if (g_changed) { strcpy(state, g_pending); strcpy(g_state, g_pending); g_changed = false; lease = lv_tick_get(); }
    else strcpy(state, g_state);
    pthread_mutex_unlock(&g_lock);
    if (g_changed || !strcmp(state, "default") || lv_tick_elaps(lease) < LEASE_SECONDS * 1000) {
        ui_claude_status_set(state);
        if (strcmp(state, "default") == 0) { led_set_color(LED_COLOR_WHITE); led_on(); }
        else if (strcmp(state, "idle") == 0) { led_set_mode_static(LED_COLOR_BLUE); led_on(); }
        else { led_set_mode_blink(LED_COLOR_GREEN, 2); led_on(); }
    } else {
        pthread_mutex_lock(&g_lock); strcpy(g_state, "default"); pthread_mutex_unlock(&g_lock);
        ui_claude_status_set("default"); led_set_color(LED_COLOR_WHITE); led_on();
    }
}

void claude_mqtt_deinit(void)
{
    g_running = false;
    pthread_join(g_thread, NULL);
    ui_claude_status_deinit();
}

