178	  ret = doubao_protocol_encode_audio(DOUBAO_EVENT_TASK_REQUEST, session_id,
179	                                     audio, audio_size, frame, sizeof(frame),
180	                                     &frame_size);
181	  if (ret < 0)
182	    {
183	      return ret;
184	    }
185	  return voice_transport_send(transport, VOICE_WS_BINARY, frame, frame_size);
186	}
