201	static void log_service_error(const doubao_packet_t *packet,
202	                              const voice_transport_t *transport)
203	{
204	  char payload[257];
205	  size_t length;
206	  size_t i;
207	
208	  length = packet->payload_size < sizeof(payload) - 1 ?
209	           packet->payload_size : sizeof(payload) - 1;
210	  for (i = 0; i < length; i++)
211	    {
212	      uint8_t value = packet->payload[i];
213	      payload[i] = value >= 0x20 && value <= 0x7e ? (char)value : '.';
214	    }
215	  payload[length] = '\0';
216	  fprintf(stderr,
217	          "doubao: service error event=%d code=%d logid=%s payload=%s\n",
218	          packet->event, packet->error_code, voice_transport_logid(transport),
219	          payload);
220	}
