222	static void handle_packet(const doubao_packet_t *packet,
223	                          const voice_transport_t *transport,
224	                          voice_player_t **player)
225	{
226	  char text[DOUBAO_REPLY_MAX];
227	
228	  if (packet->kind == DOUBAO_PACKET_ERROR)
229	    {
230	      log_service_error(packet, transport);
231	      set_state(DOUBAO_VOICE_ERROR, "豆包服务返回错误，请查看日志");
232	      return;
233	    }
234	
235	  if (packet->kind == DOUBAO_PACKET_AUDIO)
236	    {
237	      if (g_voice.config.tts_enabled && !*player)
238	        {
239	          if (voice_player_open(player, g_voice.config.playback_device,
240	                                DOUBAO_TTS_RATE, DOUBAO_TTS_CHANNELS,
241	                                DOUBAO_TTS_BITS) == 0)
242	            {
243	              set_state(DOUBAO_VOICE_PLAYING, NULL);
244	            }
245	        }
246	      if (*player)
247	        {
248	          (void)voice_player_write(*player, packet->payload,
249	                                   packet->payload_size);
250	        }
251	      return;
252	    }
253	
254	  if (packet->kind != DOUBAO_PACKET_JSON)
255	    {
256	      return;
257	    }
258	
259	  if (packet->event == DOUBAO_EVENT_ASR_RESPONSE)
260	    {
261	      if (doubao_protocol_get_text(packet->payload, packet->payload_size,
262	                                   "text", text, sizeof(text)))
263	        {
264	          pthread_mutex_lock(&g_voice.mutex);
265	          copy_text(g_voice.snapshot.user_text, sizeof(g_voice.snapshot.user_text),
266	                    text);
267	          pthread_mutex_unlock(&g_voice.mutex);
268	        }
269	    }
270	  else if (packet->event == DOUBAO_EVENT_CHAT_RESPONSE)
271	    {
272	      if (doubao_protocol_get_text(packet->payload, packet->payload_size,
273	                                   "content", text, sizeof(text)) ||
274	          doubao_protocol_get_text(packet->payload, packet->payload_size,
275	                                   "text", text, sizeof(text)))
276	        {
277	          append_reply(text);
278	        }
279	    }
280	}
