282	/* ---- 建立会话：连接 + START_CONNECTION + START_SESSION + 等待确认 ----
283	 * 返回 0 成功并把 transport 写回 *out;<0 失败。 */
284	static int establish_session(voice_transport_t **out, char *session_id,
285	                             size_t session_id_size)
286	{
287	  voice_transport_t *transport = NULL;
288	  voice_transport_config_t transport_config;
289	  char connect_id[48];
290	  char start_session_json[768];
291	  int ret;
292	
293	  make_identifier(session_id, session_id_size, "vela-session");
294	  make_identifier(connect_id, sizeof(connect_id), "vela-connect");
295	  memset(&transport_config, 0, sizeof(transport_config));
296	  transport_config.url = DOUBAO_WS_URL;
297	  transport_config.app_id = g_voice.config.app_id;
298	  transport_config.access_token = g_voice.config.access_token;
299	  transport_config.resource_id = g_voice.config.resource_id;
300	  transport_config.app_key = g_voice.config.app_key;
301	  transport_config.connect_id = connect_id;
302	
303	  ret = voice_transport_connect(&transport, &transport_config,
304	                                DOUBAO_CONNECT_TIMEOUT_MS);
305	  if (ret < 0)
306	    {
307	      return ret;
308	    }
309	  printf("doubao: connected, logid=%s\n", voice_transport_logid(transport));
310	
311	  build_start_session_json(start_session_json, sizeof(start_session_json));
312	
313	  if (send_json(transport, DOUBAO_EVENT_START_CONNECTION, session_id, "{}") < 0 ||
314	      send_json(transport, DOUBAO_EVENT_START_SESSION, session_id,
315	                start_session_json) < 0)
316	    {
317	      voice_transport_close(transport);
318	      return -EIO;
319	    }
320	
321	  /* Read back CONNECTION_STARTED + SESSION_STARTED events.  If we skip this,
322	   * the server's replies pile up in the TLS buffer and subsequent
323	   * mbedtls_ssl_write calls return WANT_READ, which the NuttX curl port
324	   * maps to CURLE_SEND_ERROR(55). */
325	  {
326	    uint8_t init_data[DOUBAO_WS_BUFFER_SIZE];
327	    voice_ws_opcode_t init_op;
328	    doubao_packet_t init_pkt;
329	    bool conn_ok = false, sess_ok = false;
330	    int init_tries = 0;
331	
332	    while ((!conn_ok || !sess_ok) && init_tries < 50 && !is_shutdown())
333	      {
334	        ret = voice_transport_receive(transport, &init_op, init_data,
335	                                      sizeof(init_data), 5000);
336	        if (ret <= 0 || init_op != VOICE_WS_BINARY)
337	          {
338	            usleep(50000); init_tries++; continue;
339	          }
340	        if (doubao_protocol_decode(init_data, (size_t)ret, &init_pkt) < 0)
341	          {
342	            usleep(50000); init_tries++; continue;
343	          }
344	        if (init_pkt.event == DOUBAO_EVENT_CONNECTION_STARTED) conn_ok = true;
345	        if (init_pkt.event == DOUBAO_EVENT_SESSION_STARTED ||
346	            init_pkt.event == 150) sess_ok = true;
347	        init_tries++;
348	      }
349	    if (!sess_ok)
350	      {
351	        voice_transport_close(transport);
352	        return -EIO;
353	      }
354	  }
355	  printf("doubao: session started\n");
356	  *out = transport;
357	  return 0;
358	}
359	
360	/* ---- 空闲等待：服务 ping 保活，直到按下或掉线或退出 ----
361	 * 返回 0 表示按下(需发起一轮)，<0 表示连接失效需重连。 */
362	static int idle_wait_for_press(voice_transport_t *transport)
363	{
364	  uint8_t buf[DOUBAO_WS_BUFFER_SIZE];
365	  voice_ws_opcode_t op;
366	
367	  while (!is_shutdown())
368	    {
369	      if (is_pressed())
370	        {
371	          return 0;
372	        }
373	      /* 短超时 receive：既服务 ping/pong，又能检测掉线；无数据即返回 0。
374	       * transport 的 receive 内部把 CLOSE 之外的错误折叠为 0,故仅 CLOSE
375	       * (返回负)触发重连。 */
376	      int ret = voice_transport_receive(transport, &op, buf,
377	                                        sizeof(buf), 200);
378	      if (ret < 0)
379	        {
380	          DVLOG("doubao: idle disconnect ret=%d", ret);
381	          return ret;   /* 掉线 → 触发重连 */
382	        }
383	      if (ret > 0)
384	        {
385	          /* 空闲期收到帧:可能是服务端下发的会话超时/错误提示。记录事件号
386	           * 以定位频繁断连原因(正常 idle 不应收到业务帧)。 */
387	          doubao_packet_t pkt;
388	          if (doubao_protocol_decode(buf, (size_t)ret, &pkt) == 0)
389	            DVLOG("doubao: idle frame kind=%d event=%d", pkt.kind, pkt.event);
390	        }
391	    }
392	  return 0;
393	}
