395	/* ---- 执行一轮对话：录音 → END_ASR → 收 ASR/TTS/Chat ----
396	 * 返回 0 成功(连接仍可用);<0 连接失效需重连。 */
397	static int run_turn(voice_transport_t *transport, const char *session_id)
398	{
399	  voice_capture_t *capture = NULL;
400	  voice_player_t *player = NULL;
401	  uint8_t audio[DOUBAO_CAPTURE_PACKET_BYTES];
402	  uint8_t received[DOUBAO_WS_BUFFER_SIZE];
403	  voice_ws_opcode_t opcode;
404	  doubao_packet_t packet;
405	  bool tts_ended = false;
406	  bool chat_ended = false;
407	  bool asr_seen = false;
408	  int ret;
409	
410	  begin_turn_snapshot();
411	  DVLOG("doubao: run_turn ENTER");
412	
413	  /* 先切 RECORDING 再开麦克风:voice_capture_open 耗时约 100ms,若此间 UI
414	   * 仍显示 IDLE,refresh 可能因某帧 wifi 抖动/状态判定把按钮 add DISABLED,
415	   * 而对"正被按住"的按钮置 DISABLED 会让 LVGL 立即发 PRESS_LOST →
416	   * action_release_cb → doubao_voice_stop 清 press。于是 worker 跑到录音
417	   * 循环时 press 已为 false,一个包都没录(sent_pkts=0),表现为按了没反应、
418	   * 卡在"等待回复超时"。提前进 RECORDING 态可消除这段 IDLE 窗口。 */
419	  set_state(DOUBAO_VOICE_RECORDING, NULL);
420	
421	  ret = voice_capture_open(&capture, g_voice.config.capture_device,
422	                           DOUBAO_CAPTURE_RATE, DOUBAO_CAPTURE_CHANNELS,
423	                           DOUBAO_CAPTURE_BITS);
424	  if (ret < 0)
425	    {
426	      set_state(DOUBAO_VOICE_ERROR, "麦克风不可用");
427	      return 0;   /* 连接仍有效,不重连 */
428	    }
429	
430	  /* 录音循环 — 从点击开始到再次点击结束期间持续上传(点击切换模式) */
431	  int sent_pkts = 0;
432	  int eagain_cnt = 0;
433	  while (is_pressed() && !is_shutdown())
434	    {
435	      /* 安全上限:每包约 20ms,1500 包≈30s。即便结束点击意外丢失(press
436	       * 未清),也不会永久卡在录音、UI 一直显示"正在录音"。 */
437	      if (sent_pkts >= 1500)
438	        {
439	          DVLOG("doubao: rec loop MAX reached, force stop");
440	          break;
441	        }
442	      ret = voice_capture_read_packet(capture, audio, sizeof(audio));
443	      if (ret == -EAGAIN)
444	        {
445	          eagain_cnt++;
446	          continue;
447	        }
448	      if (ret != (int)sizeof(audio))
449	        {
450	          voice_capture_close(capture);
451	          set_state(DOUBAO_VOICE_ERROR, "语音采集异常");
452	          return 0;
453	        }
454	      if (send_audio(transport, session_id, audio, sizeof(audio)) < 0)
455	        {
456	          voice_capture_close(capture);
457	          return -EIO;   /* 发送失败 → 重连 */
458	        }
459	      sent_pkts++;
460	    }
461	  DVLOG("doubao: recording done, sent_pkts=%d eagain=%d", sent_pkts, eagain_cnt);
462	  voice_capture_close(capture);
463	
464	  if (is_shutdown())
465	    {
466	      return 0;
467	    }
468	
469	  /* 录音过短(触摸抖动把一次点击弹成 start→立刻 stop,或误触):不发
470	   * END_ASR。豆包对空/极短音频不会给完整回复,若照常发 END_ASR 会白等
471	   * 到超时(rt recv timeout),既慢又占用连接。直接干净收尾回到 idle,
472	   * 连接仍有效不重连。20 包≈0.4s 为下限。 */
473	  if (sent_pkts < 20)
474	    {
475	      DVLOG("doubao: recording too short (%d pkts), abort turn", sent_pkts);
476	      set_state(DOUBAO_VOICE_IDLE, NULL);
477	      return 0;
478	    }
479	
480	  set_state(DOUBAO_VOICE_WAITING_RESPONSE, NULL);
481	
482	  if (send_json(transport, DOUBAO_EVENT_END_ASR, session_id, "{}") < 0)
483	    {
484	      return -EIO;
485	    }
486	  DVLOG("doubao: END_ASR sent, waiting response");
487	
488	  /* 接收 ASR + TTS + Chat 回复。
489	   * 持久连接下,上一轮的 TTS 音频(event 350 等)可能被服务端慢速推送、
490	   * 渗到本轮 END_ASR 之后;若当本轮内容处理,会先花时间收完旧音频才轮到
491	   * 本轮 ASR,表现为"一直等待回复"。故设门控:在见到本轮 ASR(ASR_START
492	   * 450 / ASR_RESPONSE 451)之前,丢弃所有帧(尤其旧 TTS 音频)。 */
493	  int empty_polls = 0;
494	  while (!chat_ended && !is_shutdown())
495	    {
496	      ret = voice_transport_receive(transport, &opcode, received,
497	                                    sizeof(received), 5000);
498	      if (ret < 0)
499	        {
500	          DVLOG("doubao: run_turn recv ret<0 (%d) -> reconnect", ret);
501	          if (player) voice_player_close(player);
502	          return -EIO;   /* 掉线 → 重连 */
503	        }
504	      if (ret == 0)
505	        {
506	          /* ret==0 可能是:PING 被处理(即时返回)、瞬时无数据、或真超时。
507	           * 只以 chat_ended(559,文字回复完)为收尾标志:TTS_ENDED(459) 常
508	           * 先于 chat 回复(550)到达,若一见 tts_ended 就 break 会把随后的
509	           * 550 漏进 idle → 该轮无文字回复。故这里不看 tts_ended,持续等到
510	           * chat_ended 或累计静默超时。 */
511	          if (++empty_polls >= 6)
512	            {
513	              DVLOG("doubao: rt recv timeout (%d empty) -> reconnect", empty_polls);
514	              if (player) voice_player_close(player);
515	              set_state(DOUBAO_VOICE_ERROR, "等待豆包回复超时");
516	              /* 超时的连接已不可信(可能半死),必须重连:此前 return 0 保留
517	               * 坏连接,下一轮复用它发 END_ASR 服务端不再响应 → 又超时,
518	               * 表现为"连着几次都没回复"。return -EIO 触发 worker 重连。 */
519	              return -EIO;
520	            }
521	          continue;
522	        }
523	      empty_polls = 0;   /* 收到有效帧,重置静默计数 */
524	      if (opcode != VOICE_WS_BINARY ||
525	          doubao_protocol_decode(received, ret, &packet) < 0)
526	        {
527	          continue;
528	        }
529	
530	      if (!asr_seen)
531	        {
532	          if (packet.event == DOUBAO_EVENT_ASR_START ||
533	              packet.event == DOUBAO_EVENT_ASR_RESPONSE)
534	            {
535	              asr_seen = true;   /* 本轮回复开始,后续正常处理 */
536	            }
537	          else
538	            {
539	              continue;          /* 上一轮残留帧,丢弃 */
540	            }
541	        }
542	
543	      DVLOG("doubao: rt event=%d kind=%d", packet.event, packet.kind);
544	      handle_packet(&packet, transport, &player);
545	      if (packet.kind == DOUBAO_PACKET_ERROR)
546	        {
547	          if (player) voice_player_close(player);
548	          return 0;   /* 服务错误但连接可能仍在 */
549	        }
550	      tts_ended |= packet.event == DOUBAO_EVENT_TTS_ENDED;
551	      chat_ended |= packet.event == DOUBAO_EVENT_CHAT_ENDED;
552	      /* 本轮结束判定:CHAT_ENDED(559) 表示文字回复已完;此时若 TTS 也已
553	       * 结束(或本就无 TTS)即收尾。服务端不保证 459/559 都发或先后顺序,
554	       * 只等 chat_ended 即可退出,避免卡在 receive 傻等 60s。 */
555	      if (chat_ended)
556	        {
557	          DVLOG("doubao: turn done (tts_ended=%d)", (int)tts_ended);
558	          break;
559	        }
560	    }
561	
562	  if (player)
563	    {
564	      voice_player_close(player);
565	      player = NULL;
566	    }
567	  set_state(DOUBAO_VOICE_IDLE, NULL);
568	  return 0;
569	}
