571	/* ---- 持久 worker:启动即连接,持续服务多轮对话 ---- */
572	static void *voice_worker(void *arg)
573	{
574	  voice_transport_t *transport = NULL;
575	  char session_id[48] = {0};
576	  bool connected = false;
577	  bool first_connect = true;   /* 仅首次连接显示"正在连接";每轮后的重连静默 */
578	
579	  (void)arg;
580	
581	  while (!is_shutdown())
582	    {
583	      if (!connected)
584	        {
585	          /* 先等 Wi-Fi 就绪(拿到 IP)再连豆包:开机时 Wi-Fi 还没连上,
586	           * 过早发起 TLS 会反复 Timeout(28)。
587	           * 豆包每轮对话(559)后会主动关连接,故 worker 需在每轮后重连。
588	           * 重连是常态,不应每次都闪"正在连接豆包"打断体验:仅首次连接
589	           * 显示 CONNECTING,后续重连保持 IDLE 静默进行。 */
590	          if (first_connect)
591	            {
592	              set_state(DOUBAO_VOICE_CONNECTING, NULL);
593	            }
594	          while (!wifi_status_is_connected() && !is_shutdown())
595	            {
596	              usleep(500 * 1000);
597	            }
598	          if (is_shutdown())
599	            {
600	              break;
601	            }
602	
603	          if (establish_session(&transport, session_id,
604	                                sizeof(session_id)) == 0)
605	            {
606	              connected = true;
607	              first_connect = false;
608	              set_state(DOUBAO_VOICE_IDLE, NULL);
609	            }
610	          else
611	            {
612	              if (is_shutdown())
613	                {
614	                  break;
615	                }
616	              /* 首次连不上才报错;重连失败静默重试,不打断 UI */
617	              if (first_connect)
618	                {
619	                  set_state(DOUBAO_VOICE_ERROR, "无法连接豆包服务");
620	                }
621	              usleep(1000 * 1000);   /* 1s 后重试 */
622	              continue;
623	            }
624	        }
625	
626	      if (idle_wait_for_press(transport) < 0)
627	        {
628	          voice_transport_close(transport);
629	          transport = NULL;
630	          connected = false;
631	          continue;
632	        }
633	      if (is_shutdown())
634	        {
635	          break;
636	        }
637	
638	      if (run_turn(transport, session_id) < 0)
639	        {
640	          voice_transport_close(transport);
641	          transport = NULL;
642	          connected = false;
643	        }
644	    }
645	
646	  if (transport)
647	    {
648	      (void)send_json(transport, DOUBAO_EVENT_FINISH_SESSION, session_id, "{}");
649	      (void)send_json(transport, DOUBAO_EVENT_FINISH_CONNECTION, session_id, "{}");
650	      voice_transport_close(transport);
651	    }
652	
653	  pthread_mutex_lock(&g_voice.mutex);
654	  g_voice.worker_running = false;
655	  pthread_mutex_unlock(&g_voice.mutex);
656	  return NULL;
657	}
