659	int doubao_voice_init(void)
660	{
661	  int ret;
662	
663	  memset(&g_voice, 0, sizeof(g_voice));
664	  pthread_mutex_init(&g_voice.mutex, NULL);
665	
666	  g_voice.initialized = true;
667	#if DOUBAO_SECRETS_AVAILABLE
668	  g_voice.config.app_id = DOUBAO_APP_ID;
669	  g_voice.config.access_token = DOUBAO_ACCESS_TOKEN;
670	  g_voice.config.resource_id = DOUBAO_RESOURCE_ID;
671	  g_voice.config.app_key = DOUBAO_APP_KEY;
672	  g_voice.config.model = DOUBAO_MODEL;
673	  g_voice.config.speaker = DOUBAO_SPEAKER;
674	  g_voice.config.capture_device = CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_CAPTURE_DEV;
675	  g_voice.config.playback_device = CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_PLAYBACK_DEV;
676	  g_voice.config.tts_enabled = 1;
677	  g_voice.snapshot.state = DOUBAO_VOICE_CONNECTING;
678	#else
679	  g_voice.snapshot.state = DOUBAO_VOICE_UNCONFIGURED;
680	  return 0;
681	#endif
682	
683	  if (!doubao_voice_is_configured())
684	    {
685	      g_voice.snapshot.state = DOUBAO_VOICE_UNCONFIGURED;
686	      return 0;
687	    }
688	
689	  /* 应用启动即拉起持久 worker,后台连接豆包并常驻等待按键 */
690	  {
691	    pthread_attr_t attr;
692	    pthread_attr_init(&attr);
693	    /* 栈 256KB:run_turn 内有 received[8192] 等大缓冲,并会经 handle_packet
694	     * 走到 nxaudio 播放路径,64KB 偏紧。放大避免深调用栈溢出崩溃。 */
695	    pthread_attr_setstacksize(&attr, 262144);
696	    g_voice.worker_running = true;
697	    ret = pthread_create(&g_voice.worker, &attr, voice_worker, NULL);
698	    pthread_attr_destroy(&attr);
699	  }
700	  if (ret != 0)
701	    {
702	      g_voice.worker_running = false;
703	      set_state(DOUBAO_VOICE_ERROR, "worker 启动失败");
704	      return -ret;
705	    }
706	  return 0;
707	}
708	
709	void doubao_voice_deinit(void)
710	{
711	  bool join = false;
712	
713	  if (!g_voice.initialized)
714	    {
715	      return;
716	    }
717	
718	  pthread_mutex_lock(&g_voice.mutex);
719	  g_voice.shutdown = true;
720	  g_voice.press = false;
721	  join = g_voice.worker_running;
722	  pthread_mutex_unlock(&g_voice.mutex);
723	
724	  if (join)
725	    {
726	      (void)pthread_join(g_voice.worker, NULL);
727	    }
728	  pthread_mutex_destroy(&g_voice.mutex);
729	  memset(&g_voice, 0, sizeof(g_voice));
730	}
731	
732	int doubao_voice_start(void)
733	{
734	  if (!g_voice.initialized || !doubao_voice_is_configured())
735	    {
736	      return -ENOKEY;
737	    }
738	  pthread_mutex_lock(&g_voice.mutex);
739	  g_voice.press = true;
740	  pthread_mutex_unlock(&g_voice.mutex);
741	  return 0;
742	}
743	
744	int doubao_voice_stop(void)
745	{
746	  if (!g_voice.initialized)
747	    {
748	      return -EINVAL;
749	    }
750	  pthread_mutex_lock(&g_voice.mutex);
751	  g_voice.press = false;
752	  pthread_mutex_unlock(&g_voice.mutex);
753	  return 0;
754	}
755	
756	int doubao_voice_reset(void)
757	{
758	  if (!g_voice.initialized)
759	    {
760	      return -EINVAL;
761	    }
762	  pthread_mutex_lock(&g_voice.mutex);
763	  g_voice.snapshot.user_text[0] = '\0';
764	  g_voice.snapshot.assistant_text[0] = '\0';
765	  g_voice.snapshot.error_text[0] = '\0';
766	  pthread_mutex_unlock(&g_voice.mutex);
767	  return 0;
768	}
769	
770	bool doubao_voice_is_configured(void)
771	{
772	#if DOUBAO_SECRETS_AVAILABLE
773	  return g_voice.config.app_id && g_voice.config.app_id[0] &&
774	         g_voice.config.access_token && g_voice.config.access_token[0] &&
775	         strcmp(g_voice.config.app_id, "replace-with-your-app-id") != 0;
776	#else
777	  return false;
778	#endif
779	}
780	
781	void doubao_voice_get_snapshot(doubao_voice_snapshot_t *snapshot)
782	{
783	  if (!snapshot)
784	    {
785	      return;
786	    }
787	  pthread_mutex_lock(&g_voice.mutex);
788	  *snapshot = g_voice.snapshot;
789	  pthread_mutex_unlock(&g_voice.mutex);
790	}
