1	/****************************************************************************
2	 * src/doubao/voice.c
3	 * Full-duplex continuous-conversation coordinator for Doubao RealtimeAPI.
4	 *
5	 * "开始会话" 建立一条 WebSocket 连接并进入全双工 session_loop:单线程内
6	 * 交替执行 [非阻塞采集上传] + [非阻塞排空接收 ASR/Chat/TTS] + [播放],
7	 * 服务端 VAD 自动断句,多轮连续问答,直到 "停止会话" 断连(不保活)。
8	 *
9	 * 外放喇叭无硬件 AEC:AI 播放期间门控麦克风上传(不上传)以根治自问自答
10	 * 自循环;可选本地能量 VAD 在播放期间检测用户开口,命中即立即停播实现
11	 * barge-in(见 DOUBAO_BARGE_IN_ENABLED)。
12	 *
13	 * 并发模型为单线程交替而非双线程:transport 基于单个 libcurl easy 句柄,
14	 * send 在背压路径会 curl_easy_recv 同一 fd,与并发 recv 竞争会破坏 WS
15	 * 分帧;采集侧 snd_pcm_wait 提供 ~20ms 节拍,receive 用 timeout=0 非阻塞
16	 * 排空,天然可单线程驱动。
17	 *
18	 * Linux adaptation — ALSA audio, pthread worker, mutex-protected snapshot.
19	 ****************************************************************************/
20	
21	#include "voice.h"
22	#include "protocol.h"
23	#include "capture.h"
24	#include "player.h"
25	#include "transport.h"
26	#include "wake/wake_reply.h"
27	
28	#include <curl/curl.h>
29	#include <json-c/json.h>
30	#include <ctype.h>
31	#include <errno.h>
32	#include <fcntl.h>
33	#include <pthread.h>
34	#include <stdio.h>
35	#include <stdlib.h>
36	#include <string.h>
37	#include <sys/stat.h>
38	#include <time.h>
39	#include <unistd.h>
40	
41	#if __has_include("secret.h")
42	#  include "secret.h"
43	#  define DOUBAO_SECRETS_AVAILABLE 1
44	#else
45	#  define DOUBAO_SECRETS_AVAILABLE 0
46	#  define DOUBAO_APP_ID ""
47	#  define DOUBAO_ACCESS_TOKEN ""
48	#  define DOUBAO_MODEL ""
49	#  define DOUBAO_SPEAKER ""
50	#endif
51	
52	/* 采集与播放统一走 ALSA default(见 etc/asound.conf:asym → 采集 dsnoop、
53	 * 播放 dmix),使外部 sherpa-onnx KWS 唤醒进程与豆包全/半双工可同时共享
54	 * 麦克风与扬声器,避免独占 plughw 造成的收音失败/播放收尾卡死。 */
55	#define DOUBAO_CAPTURE_DEV        "default"
56	#define DOUBAO_PLAYBACK_DEV       "default"
57	#define DOUBAO_FRAME_CAPACITY     (DOUBAO_WS_BUFFER_SIZE + 1024)
58	
59	/* CHAT_ENDED 后继续等待滞后 TTS 音频的静默超时(ms)。 */
60	#define DOUBAO_DRAIN_TIMEOUT_MS   5000
61	#define DOUBAO_WAKE_PREROLL_FRAMES 15  /* 300ms @ 20ms, preserve speech onset */
62	
63	typedef struct doubao_voice_context_s {
64	    pthread_mutex_t mutex;
65	    pthread_t worker;
66	    bool initialized;
67	    bool worker_running;   /* 持久 worker 线程存活 */
68	    bool shutdown;         /* deinit 请求退出 worker */
69	    bool talking;          /* 按钮全双工会话开关。 */
70	    bool wake_turn_pending; /* wake worker 已释放 ALSA，请求一轮半双工会话 */
71	    bool abort_playback;   /* 音乐抢占：立即中止 TTS 并关闭当前连接 */
72	    bool stop_playback;    /* 用户暂停：立即中止 TTS，保留当前连接 */
73	    doubao_wake_control_cb_t wake_control_cb;
74	    void *wake_control_userdata;
75	    /* 文字问答(ChatTextQuery):程序经 doubao_voice_ask_text 提交一句文本,
76	     * session_loop 在待命(非 talking)分支取出发送 501,回复走与语音相同的
77	     * 550文字气泡+352 TTS 播放路径。仅在待命态受理,与全双工永不并发。 */
78	    bool query_pending;                    /* 有待发送的文字 query */
79	    char pending_query[DOUBAO_TEXT_MAX];   /* 待发送的文本(原文,发送时才转义) */
80	    /* greet_then_wake:本条 query 是"问候+收音"组合原语提交的。session_loop 取
81	     * 出该 query 时把此标志转到本轮局部变量;该轮问候 TTS 播完回 IDLE 时,不停在
82	     * 待命,而是置 wake_turn_pending 并 return RC_WAKE_TURN,由 worker 顺势接一轮
83	     * 半双工收音。实现"先问候后收音"全程单线程串行。 */
84	    bool greet_then_wake;
85	    /* 本轮 RC_WAKE_TURN 是否由 greet_then_wake 链路产生(区别于关键词唤醒)。
86	     * greet 链路里豆包问候语已充当"回应",run_wake_turn 开头就无须再播唤醒确认
87	     * 音(否则用户听到问候后、收音前会突兀多响一声)。仅 worker 线程串行读写,
88	     * session_loop 返回 RC_WAKE_TURN 前置位、run_wake_turn 读后即可忽略。 */
89	    bool wake_turn_is_greet;
90	    /* greet_then_talk:本条 query 是"问候+连续对话"组合原语(正脸注视)提交的。
91	     * 与 greet_then_wake 的区别在问候 TTS 播完后:后者接一轮半双工单轮收音
92	     * (run_wake_turn),本者置 talking=true 转入全双工 session_loop 连续对话,直到
93	     * face_tracker 检测正脸离开经 ubus stop_talk 结束。session_loop 取出该 query
94	     * 时转到本轮局部变量。 */
95	    bool greet_then_talk;
96	    char dialog_id[DOUBAO_DIALOG_ID_MAX];  /* 跨实时 session 的服务端上下文标识 */
97	    doubao_history_turn_t history[DOUBAO_HISTORY_MAX_TURNS];
98	    size_t history_count;
99	    doubao_voice_snapshot_t snapshot;
100	    doubao_voice_config_t config;
101	} doubao_voice_context_t;
102	
103	static doubao_voice_context_t g_voice;
104	
105	/* session_loop 内部返回码:区分"正常停止(回 IDLE)"与"掉线需重连"。 */
106	#define RC_STOP       0
107	#define RC_RECONNECT  (-1)
108	#define RC_WAKE_TURN  1
109	
110	static uint64_t now_ms(void)
111	{
112	    struct timespec ts;
113	    clock_gettime(CLOCK_MONOTONIC, &ts);
114	    return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
115	}
116	
117	static void copy_text(char *dst, size_t size, const char *src)
118	{
119	    if (!dst || size == 0) return;
120	    if (!src) { dst[0] = '\0'; return; }
121	    strncpy(dst, src, size - 1);
122	    dst[size - 1] = '\0';
123	}
124	
125	static bool dialog_id_is_valid(const char *id)
126	{
127	    size_t length;
128	
129	    if (!id || !id[0])
130	        return false;
131	    length = strlen(id);
132	    if (length >= DOUBAO_DIALOG_ID_MAX)
133	        return false;
134	    for (size_t i = 0; i < length; i++) {
135	        unsigned char c = (unsigned char)id[i];
136	        if (!isalnum(c) && c != '_' && c != '-')
137	            return false;
138	    }
139	    return true;
140	}
141	
142	static void make_dialog_id(char *out, size_t out_size)
143	{
144	    struct timespec ts;
145	    static unsigned int next_id;
146	
147	    clock_gettime(CLOCK_REALTIME, &ts);
148	    snprintf(out, out_size, "vela-%lx-%lx-%x-%x", (unsigned long)ts.tv_sec,
149	             (unsigned long)ts.tv_nsec, (unsigned int)getpid(), ++next_id);
150	}
151	
152	static void load_dialog_id(void)
153	{
154	    char loaded[DOUBAO_DIALOG_ID_MAX];
155	    char temporary_path[sizeof(DOUBAO_DIALOG_ID_PATH) + 24];
156	    int fd;
157	    ssize_t read_size;
158	    bool saved = false;
159	
160	    fd = open(DOUBAO_DIALOG_ID_PATH, O_RDONLY | O_CLOEXEC);
161	    if (fd >= 0) {
162	        read_size = read(fd, loaded, sizeof(loaded) - 1);
163	        close(fd);
164	        if (read_size > 0) {
165	            loaded[read_size] = '\0';
166	            loaded[strcspn(loaded, "\r\n")] = '\0';
167	            if (dialog_id_is_valid(loaded)) {
168	                copy_text(g_voice.dialog_id, sizeof(g_voice.dialog_id), loaded);
169	                DOUBAO_LOG("dialog context loaded");
170	                return;
171	            }
172	        }
173	        fprintf(stderr, "doubao: ignore invalid dialog id file\n");
174	    }
175	
176	    make_dialog_id(g_voice.dialog_id, sizeof(g_voice.dialog_id));
177	    snprintf(temporary_path, sizeof(temporary_path), "%s.%ld.tmp",
178	             DOUBAO_DIALOG_ID_PATH, (long)getpid());
179	    fd = open(temporary_path, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0600);
180	    if (fd >= 0) {
181	        if (write(fd, g_voice.dialog_id, strlen(g_voice.dialog_id)) >= 0 &&
182	            write(fd, "\n", 1) == 1 && fsync(fd) == 0) {
183	            if (close(fd) == 0 && rename(temporary_path, DOUBAO_DIALOG_ID_PATH) == 0)
184	                saved = true;
185	        } else {
186	            close(fd);
187	        }
188	    }
189	    if (!saved) {
190	        unlink(temporary_path);
191	        fprintf(stderr, "doubao: dialog id is temporary; persistence unavailable: %s\n",
192	                strerror(errno));
193	        return;
194	    }
195	    DOUBAO_LOG("dialog context created");
196	}
