295	static void load_server_history(const uint8_t *payload, size_t payload_size)
296	{
297	    doubao_history_turn_t parsed[DOUBAO_HISTORY_MAX_TURNS];
298	    struct json_object *root = NULL;
299	    struct json_object *items = NULL;
300	    struct json_tokener *tokener = NULL;
301	    size_t count = 0;
302	    int item_count;
303	
304	    tokener = json_tokener_new();
305	    if (!tokener)
306	        return;
307	    root = json_tokener_parse_ex(tokener, (const char *)payload, (int)payload_size);
308	    if (json_tokener_get_error(tokener) != json_tokener_success || !root ||
309	        !json_object_object_get_ex(root, "items", &items) ||
310	        !json_object_is_type(items, json_type_array)) {
311	        fprintf(stderr, "doubao: ignore malformed conversation history\n");
312	        goto done;
313	    }
314	
315	    item_count = json_object_array_length(items);
316	    for (int i = 0; i + 1 < item_count && count < DOUBAO_HISTORY_MAX_TURNS; i++) {
317	        struct json_object *user = json_object_array_get_idx(items, i);
318	        struct json_object *assistant = json_object_array_get_idx(items, i + 1);
319	        struct json_object *user_role = NULL;
320	        struct json_object *assistant_role = NULL;
321	        struct json_object *user_text = NULL;
322	        struct json_object *assistant_text = NULL;
323	
324	        if (!json_object_object_get_ex(user, "role", &user_role) ||
325	            !json_object_object_get_ex(assistant, "role", &assistant_role) ||
326	            !json_object_object_get_ex(user, "text", &user_text) ||
327	            !json_object_object_get_ex(assistant, "text", &assistant_text) ||
328	            strcmp(json_object_get_string(user_role), "user") != 0 ||
329	            strcmp(json_object_get_string(assistant_role), "assistant") != 0) {
330	            continue;
331	        }
332	
333	        copy_text(parsed[count].user_text, sizeof(parsed[count].user_text),
334	                  json_object_get_string(user_text));
335	        copy_text(parsed[count].assistant_text, sizeof(parsed[count].assistant_text),
336	                  json_object_get_string(assistant_text));
337	        count++;
338	        i++;
339	    }
340	
341	    pthread_mutex_lock(&g_voice.mutex);
342	    memcpy(g_voice.history, parsed, count * sizeof(parsed[0]));
343	    g_voice.history_count = count;
344	    g_voice.snapshot.history_revision++;
345	    pthread_mutex_unlock(&g_voice.mutex);
346	    DOUBAO_LOG("conversation history retrieved: %zu turns", count);
347	
348	done:
349	    if (root)
350	        json_object_put(root);
351	    json_tokener_free(tokener);
352	}
