389	/* 把 src 转义为合法 JSON 字符串内容(不含外层引号)写入 dst。控制字符与
390	 * " \ 做转义,截断到 dst 容量,保证结果可安全嵌入 {"content":"..."}。 */
391	static void json_escape(char *dst, size_t dst_size, const char *src)
392	{
393	    size_t o = 0;
394	    if (!dst || dst_size == 0) return;
395	    for (const char *p = src ? src : ""; *p && o + 2 < dst_size; p++) {
396	        unsigned char c = (unsigned char)*p;
397	        switch (c) {
398	            case '"':  if (o + 2 < dst_size) { dst[o++]='\\'; dst[o++]='"'; } break;
399	            case '\\': if (o + 2 < dst_size) { dst[o++]='\\'; dst[o++]='\\'; } break;
400	            case '\n': if (o + 2 < dst_size) { dst[o++]='\\'; dst[o++]='n'; } break;
401	            case '\r': if (o + 2 < dst_size) { dst[o++]='\\'; dst[o++]='r'; } break;
402	            case '\t': if (o + 2 < dst_size) { dst[o++]='\\'; dst[o++]='t'; } break;
403	            default:
404	                if (c < 0x20) {
405	                    /* 其它控制字符转 \u00XX(需 6 字节余量) */
406	                    if (o + 6 < dst_size) {
407	                        static const char hex[] = "0123456789abcdef";
408	                        dst[o++]='\\'; dst[o++]='u'; dst[o++]='0'; dst[o++]='0';
409	                        dst[o++]=hex[(c>>4)&0xf]; dst[o++]=hex[c&0xf];
410	                    }
411	                } else {
412	                    dst[o++] = (char)c;   /* UTF-8 多字节原样透传 */
413	                }
414	        }
415	    }
416	    dst[o] = '\0';
417	}
