419	/* 发送纯文本 query(ChatTextQuery=501):{"content":"<escaped>"}。
420	 * 仅由 session_loop 在待命(非 talking)分支调用,复用常驻连接。 */
421	static int send_text_query(voice_transport_t *t, const char *session_id,
422	                           const char *query)
423	{
424	    char esc[DOUBAO_TEXT_MAX * 2 + 8];
425	    char json[DOUBAO_TEXT_MAX * 2 + 32];
426	    json_escape(esc, sizeof(esc), query);
427	    snprintf(json, sizeof(json), "{\"content\":\"%s\"}", esc);
428	    return send_json(t, DOUBAO_EVENT_CHAT_TEXT_QUERY, session_id, json);
429	}
