479	/* 20ms 帧内 |sample| 均值(int16 绝对值均值),用于 VAD 与回声标定。 */
480	static unsigned frame_energy(const uint8_t *frame, size_t size)
481	{
482	    const int16_t *s = (const int16_t *)frame;
483	    size_t n = size / 2;
484	    uint64_t sum = 0;
485	    size_t i;
486	
487	    if (n == 0) return 0;
488	    for (i = 0; i < n; i++) {
489	        int v = s[i];
490	        sum += (uint64_t)(v < 0 ? -v : v);
491	    }
492	    return (unsigned)(sum / n);
493	}
