495	/* 本地能量 VAD:帧能量超阈计一帧,连续 VAD_ON_FRAMES 帧判定"用户开口"。
496	 * run 为跨帧命中计数(调用方持有并复位)。 */
497	static bool energy_vad(const uint8_t *frame, size_t size, unsigned *run)
498	{
499	    if (frame_energy(frame, size) > DOUBAO_VAD_ON_THRESHOLD)

498	{
499	    if (frame_energy(frame, size) > DOUBAO_VAD_ON_THRESHOLD)
500	        (*run)++;
501	    else
502	        *run = 0;
503	    return *run >= DOUBAO_VAD_ON_FRAMES;
504	}
