506	/* 处理一帧服务端数据。全双工多轮:见到用户话首(首个 ASR_START/ASR_RESPONSE
507	 * 且当前轮未开)即 begin_turn_snapshot 开新轮;CHAT_ENDED 关闭本轮。
508	 * last_audio_ms 记录最近一次收到 TTS 音频的时刻,供播放排空窗口判定。
509	 * tts_ended(可为 NULL):收到 TTS_ENDED(359)——服务端本轮 TTS 全部发完的权威
510	 * 信号——置真;新一轮 ASR 开始时复位。收尾判据据此免去"静默 5 秒"的兜底等待,
511	 * 收到 359 即可关播放器(voice_player_close 内部 drain 保证尾音播完不丢)。 */
512	static void handle_fd(const doubao_packet_t *packet,
513	                      const voice_transport_t *transport,
514	                      voice_player_t **player,
515	                      bool *turn_open, bool *chat_ended,
516	                      uint64_t *last_audio_ms,
517	                      bool *discard, bool *tts_ended)
518	{
519	    char text[DOUBAO_REPLY_MAX];
520	
521	    if (packet->kind == DOUBAO_PACKET_ERROR) {
522	        char payload[257];
523	        size_t len = packet->payload_size < sizeof(payload) - 1
524	                     ? packet->payload_size : sizeof(payload) - 1;
525	        size_t i;
526	        for (i = 0; i < len; i++) {
527	            uint8_t v = packet->payload[i];
528	            payload[i] = v >= 0x20 && v <= 0x7e ? (char)v : '.';
529	        }
530	        payload[len] = '\0';
531	        fprintf(stderr, "doubao: service error event=%d code=%d logid=%s "
532	                "payload=%s\n",
533	                packet->event, packet->error_code,
534	                voice_transport_logid(transport), payload);
535	        /* 会话中的 service error(最常见 DialogAudioIdleTimeout:服务端判定
536	         * 音频空闲把连接踢掉)是可恢复的,由 session_loop 返回 RC_STOP 触发
537	         * worker 后台无缝重连。此处不再置 UI 为 ERROR,否则会闪"出错,点击开始
538	         * 重试";重连期间 worker 也不置 CONNECTING(见 connected_once),保持
539	         * 当前"聆听中/待命"提示,用户无感知。真正的致命错误(鉴权等)发生在
540	         * 首次 establish_session 阶段,会在那里正确显示 ERROR。 */
541	        return;
542	    }
543	
544	    if (packet->kind == DOUBAO_PACKET_AUDIO) {
545	        /* 语音停止(挂断)后,本轮已被 abort,服务端仍会推来残留/滞后的 350
546	         * 音频。discard 为真则静默丢弃、不重开 player,避免"点了停止又自己响"。
547	         * discard 仅由语音停止置位,开始对话/文字 query 时清除,故不误伤二者。 */
548	        if (*discard)
549	            return;
550	        if (g_voice.config.tts_enabled && !*player) {
551	            if (voice_player_open(player, g_voice.config.playback_device,
552	                                  DOUBAO_TTS_RATE, DOUBAO_TTS_CHANNELS,
553	                                  DOUBAO_TTS_BITS) == 0) {
554	                set_state(DOUBAO_VOICE_PLAYING, NULL);
555	                DOUBAO_LOG("player opened (TTS start)");
556	            }
557	        }
558	        if (*player)
559	            (void)voice_player_write(*player, packet->payload,
560	                                     packet->payload_size);
561	        *last_audio_ms = now_ms();
562	        return;
563	    }
564	
565	    if (packet->kind != DOUBAO_PACKET_JSON)
566	        return;
567	
568	    if (packet->event == DOUBAO_EVENT_CONVERSATION_RETRIEVED) {
569	        load_server_history(packet->payload, packet->payload_size);
570	        return;
571	    }
572	
573	    /* 用户话首 → 开新一轮(turn_seq++、清空文字),UI 据此沉淀历史气泡 */
574	    if ((packet->event == DOUBAO_EVENT_ASR_START ||
575	         packet->event == DOUBAO_EVENT_ASR_RESPONSE) && !*turn_open) {
576	        begin_turn_snapshot();
577	        *turn_open = true;
578	        *chat_ended = false;
579	        if (tts_ended) *tts_ended = false;  /* 新一轮:清上轮的 TTS 结束标志 */
580	        set_state(DOUBAO_VOICE_RECORDING, NULL);
581	    }
582	
583	    if (packet->event == DOUBAO_EVENT_ASR_RESPONSE) {
584	        if (doubao_protocol_get_text(packet->payload, packet->payload_size,
585	                                     "text", text, sizeof(text))) {
586	            DOUBAO_LOG("ASR text=%s", text);
587	            pthread_mutex_lock(&g_voice.mutex);
588	            copy_text(g_voice.snapshot.user_text,
589	                      sizeof(g_voice.snapshot.user_text), text);
590	            pthread_mutex_unlock(&g_voice.mutex);
591	        }
592	    } else if (packet->event == DOUBAO_EVENT_CHAT_RESPONSE) {
593	        if (doubao_protocol_get_text(packet->payload, packet->payload_size,
594	                                     "content", text, sizeof(text)) ||
595	            doubao_protocol_get_text(packet->payload, packet->payload_size,
596	                                     "text", text, sizeof(text))) {
597	            DOUBAO_LOG("chat text=%s", text);
598	            append_reply(text);
599	        }
600	    } else if (packet->event == DOUBAO_EVENT_CHAT_ENDED) {
601	        *chat_ended = true;
602	        *last_audio_ms = now_ms(); /* 给首帧或尾帧 TTS 留出排空窗口 */
603	        *turn_open = false;   /* 本轮结束,下一个 ASR 开新轮 */
604	    } else if (packet->event == DOUBAO_EVENT_TTS_ENDED) {
605	        /* 服务端本轮 TTS 全部发完的权威信号。收尾判据据此立即关播放器,
606	         * 免去"CHAT_ENDED 后静默 5 秒"的保守兜底等待。359 常滞后于 559 到达,
607	         * 与 chat_ended 联合判定;若异常未到,静默超时仍兜底。 */
608	        if (tts_ended) *tts_ended = true;
609	    }
610	}
611	
612	/* ---- 在已连接的 transport 上启动一个 Session（不含 TCP/TLS 建连）----
613	 * 复用常驻连接切换 Session 时调用:发送 START_SESSION + 等待 SESSION_STARTED,
614	 * 全双工额外请求历史。返回 0 成功,<0 表示需由调用方关闭连接后重连。 */
615	static int start_session_on_transport(voice_transport_t *transport,
616	                                      char *session_id, size_t session_id_size,
617	                                      bool wake_half_duplex)
618	{
619	    char start_session_json[2048];
620	    int ret;
621	
622	    make_identifier(session_id, session_id_size, "vela-session");
623	
624	    if (wake_half_duplex)
625	        build_wake_session_json(start_session_json, sizeof(start_session_json));
626	    else
627	        build_start_session_json(start_session_json, sizeof(start_session_json));
628	
629	    if (send_json(transport, DOUBAO_EVENT_START_SESSION,
630	                  session_id, start_session_json) < 0)
631	        return -EIO;
632	
633	    /* 等待 SESSION_STARTED(150)。连接已建立,无需再等 CONNECTION_STARTED。 */
634	    {
635	        uint8_t buf[DOUBAO_WS_BUFFER_SIZE];
636	        voice_ws_opcode_t op;
637	        doubao_packet_t pkt;
638	        bool sess_ok = false;
639	        int tries = 0;
640	
641	        while (!sess_ok && tries < 10 && !is_shutdown()) {
642	            ret = voice_transport_receive(transport, &op, buf, sizeof(buf), 1000);
643	            tries++;
644	            if (ret <= 0 || op != VOICE_WS_BINARY)
645	                continue;
646	            if (doubao_protocol_decode(buf, (size_t)ret, &pkt) < 0)
647	                continue;
648	            if (pkt.event == DOUBAO_EVENT_SESSION_STARTED)
649	                sess_ok = true;
650	        }
651	        if (!sess_ok)
652	            return -EIO;
653	    }
654	    DOUBAO_LOG("session started (reused connection)");
655	    if (!wake_half_duplex &&
656	        send_json(transport, DOUBAO_EVENT_CONVERSATION_RETRIEVE,
657	                  session_id, "{}") < 0)
658	        fprintf(stderr, "doubao: conversation history retrieve request failed\n");
659	    return 0;
660	}
661	
662	/* ---- 结束当前 Session 并等待 SESSION_FINISHED（保留 WebSocket 连接）----
663	 * 供 Session 间无缝切换。等待确认可让下一个 START_SESSION 不与旧会话交叠。
664	 * 期间到达的音频/文字帧直接丢弃(本轮已收尾)。返回 0 表示可继续复用连接。 */
665	static int finish_session_keep_connection(voice_transport_t *transport,
666	                                          const char *session_id)
667	{
668	    uint8_t buf[DOUBAO_WS_BUFFER_SIZE];
669	    voice_ws_opcode_t op;
670	    doubao_packet_t pkt;
671	    int tries = 0;
672	    int ret;
673	
674	    if (send_json(transport, DOUBAO_EVENT_FINISH_SESSION, session_id, "{}") < 0)
675	        return -EIO;
676	
677	    while (tries < 20 && !is_shutdown()) {
678	        ret = voice_transport_receive(transport, &op, buf, sizeof(buf), 1000);
679	        tries++;
680	        if (ret < 0)
681	            return -EIO;
682	        if (ret == 0)
683	            return -EIO;   /* 超时:连接可能已不可用,交调用方重连 */
684	        if (op != VOICE_WS_BINARY)
685	            continue;
686	        if (doubao_protocol_decode(buf, (size_t)ret, &pkt) < 0)
687	            continue;
688	        if (pkt.event == DOUBAO_EVENT_SESSION_FINISHED)
689	            return 0;
690	    }
691	    return -EIO;
692	}
693	
694	/* ---- 建立会话：连接 + START_CONNECTION + START_SESSION + 等待确认 ---- */
695	static int establish_session_with_json(voice_transport_t **out, char *session_id,
696	                                       size_t session_id_size,
697	                                       bool wake_half_duplex)
698	{
699	    voice_transport_t *transport = NULL;
700	    voice_transport_config_t tcfg;
701	    char connect_id[48];
702	    char start_session_json[2048];
703	    int ret = -EIO;
704	
705	    make_identifier(session_id, session_id_size, "vela-session");
706	    make_identifier(connect_id, sizeof(connect_id), "vela-connect");
707	
708	    memset(&tcfg, 0, sizeof(tcfg));
709	    tcfg.url = DOUBAO_WS_URL;
710	    tcfg.app_id = g_voice.config.app_id;
711	    tcfg.access_token = g_voice.config.access_token;
712	    tcfg.resource_id = g_voice.config.resource_id;
713	    tcfg.app_key = g_voice.config.app_key;
714	    tcfg.connect_id = connect_id;
715	
716	    for (int attempt = 1; attempt <= 3 && !is_shutdown(); attempt++) {
717	        ret = voice_transport_connect(&transport, &tcfg,
718	                                      DOUBAO_CONNECT_TIMEOUT_MS);
719	        if (ret == 0)
720	            break;
721	        if (attempt < 3)
722	            usleep(300 * 1000);
723	    }
724	    if (ret < 0)
725	        return ret;
726	    DOUBAO_LOG("connected, logid=%s", voice_transport_logid(transport));
727	
728	    if (wake_half_duplex)
729	        build_wake_session_json(start_session_json, sizeof(start_session_json));
730	    else
731	        build_start_session_json(start_session_json, sizeof(start_session_json));
732	
733	    if (send_json(transport, DOUBAO_EVENT_START_CONNECTION,
734	                  session_id, "{}") < 0 ||
735	        send_json(transport, DOUBAO_EVENT_START_SESSION,
736	                  session_id, start_session_json) < 0) {
737	        voice_transport_close(transport);
738	        return -EIO;
739	    }
740	
741	    /* 等待 CONNECTION_STARTED(50) + SESSION_STARTED(150) */
742	    {
743	        /* 64KB 接收缓冲改堆分配:与 send_json 的 66KB frame[] 叠加会顶高本条
744	         * (建连)路径的栈峰值,堆分配削掉这一块,连同 8MB 线程栈根治断网重试
745	         * 爆栈崩溃。 */
746	        uint8_t *buf = malloc(DOUBAO_WS_BUFFER_SIZE);
747	        voice_ws_opcode_t op;
748	        doubao_packet_t pkt;
749	        bool conn_ok = false, sess_ok = false;
750	        int tries = 0;
751	
752	        if (!buf) {
753	            voice_transport_close(transport);
754	            return -ENOMEM;
755	        }
756	        while ((!conn_ok || !sess_ok) && tries < 10 && !is_shutdown()) {
757	            ret = voice_transport_receive(transport, &op, buf,
758	                                          DOUBAO_WS_BUFFER_SIZE, 1000);
759	            if (ret <= 0 || op != VOICE_WS_BINARY) {
760	                usleep(50000);
761	                tries++;
762	                continue;
763	            }
764	            if (doubao_protocol_decode(buf, (size_t)ret, &pkt) < 0) {
765	                usleep(50000);
766	                tries++;
767	                continue;
768	            }
769	            if (pkt.event == DOUBAO_EVENT_CONNECTION_STARTED)
770	                conn_ok = true;
771	            if (pkt.event == DOUBAO_EVENT_SESSION_STARTED)
772	                sess_ok = true;
773	            tries++;
774	        }
775	        free(buf);
776	        if (!sess_ok) {
777	            voice_transport_close(transport);
778	            return -EIO;
779	        }
780	    }
781	    DOUBAO_LOG("session started");
782	    if (!wake_half_duplex &&
783	        send_json(transport, DOUBAO_EVENT_CONVERSATION_RETRIEVE,
784	                  session_id, "{}") < 0)
785	        fprintf(stderr, "doubao: conversation history retrieve request failed\n");
786	    *out = transport;
787	    return 0;
788	}
789	
790	/* 唤醒后的一轮半双工对话。复用 worker 常驻的 WebSocket 连接:入口先在同一
791	 * 连接上把全双工 Session 换成 push_to_talk Session(省去 TCP/TLS 建连,消除
792	 * "正在连接豆包"等待);结束后再结束该 Session 并把连接交还 worker 复用。
793	 * *transport_io 进入时为一条无活动 Session 的连接(或 NULL);返回时为可复用
794	 * 连接或 NULL(连接已失效,由 worker 重连)。 */
795	static int run_wake_turn(voice_transport_t **transport_io,
796	                         char *session_id, size_t session_id_size)
797	{

797	{
798	    voice_transport_t *transport = *transport_io;
799	    voice_capture_t *capture = NULL;
800	    voice_player_t *player = NULL;
801	    uint8_t audio[DOUBAO_CAPTURE_PACKET_BYTES];
802	    uint8_t preroll[DOUBAO_WAKE_PREROLL_FRAMES][DOUBAO_CAPTURE_PACKET_BYTES];
803	    size_t preroll_count = 0;
804	    size_t preroll_next = 0;
805	    uint8_t received[DOUBAO_WS_BUFFER_SIZE];
806	    voice_ws_opcode_t opcode;
807	    doubao_packet_t packet;
808	    uint64_t started_ms = 0;
809	    uint64_t last_audio_ms = 0;
810	    unsigned onset_run = 0;
811	    unsigned silence_run = 0;
812	    bool speech_started = false;
813	    bool turn_open = false;
814	    bool chat_ended = false;
815	    bool tts_ended = false;   /* 收到 TTS_ENDED(359):本轮 TTS 已全部发完 */
816	    bool keep_conn = false;   /* 收尾时是否保留连接供 worker 复用 */
817	    bool discard = false;   /* 半双工唤醒会话不丢弃 TTS(无"停止对话挂断"语义) */
818	    int ret = RC_STOP;
819	    const char *exit_reason = "unknown";
820	
821	    /* 全双工 Session 已由 worker 结束,扬声器空闲,先播随机确认音。
822	     * 正脸问候链路(greet_then_wake)例外:豆包问候语已充当回应,再插一声确认
823	     * 音会突兀,故跳过,直接进入收音。 */
824	    if (!g_voice.wake_turn_is_greet) {
825	        if (wake_reply_play_random() < 0)
826	            fprintf(stderr, "doubao: wake reply playback failed\n");
827	    } else {
828	        DOUBAO_LOG("greet-chained wake turn: skip confirmation chime");
829	    }
830	    g_voice.wake_turn_is_greet = false;  /* 每轮独立判定,用后即清 */
831	
832	    /* 复用常驻连接切换到 push_to_talk Session;失败才回退到全新建连。 */
833	    if (transport &&
834	        start_session_on_transport(transport, session_id, session_id_size,
835	                                   true) < 0) {
836	        voice_transport_close(transport);
837	        transport = NULL;
838	    }
839	    if (!transport) {
840	        set_state(DOUBAO_VOICE_CONNECTING, NULL);
841	        if (establish_session_with_json(&transport, session_id,
842	                                        session_id_size, true) != 0) {
843	            exit_reason = "connect failed";
844	            set_state(DOUBAO_VOICE_ERROR, "无法连接豆包服务");
845	            *transport_io = NULL;
846	            goto done;
847	        }
848	    }
849	    *transport_io = transport;
850	    keep_conn = true;   /* 连接已就绪且健康,除非后续 send/接收失败 */
851	
852	    /* capture open 短重试:正常唤醒路径 wake worker 已在同线程释放麦克风,首次
853	     * 即成功;但 greet_then_wake 链路是异步通知 wake service 停(跨线程),ALSA
854	     * 释放可能滞后,这里最多重试 ~600ms 吸收该延迟,避免 busy 直接失败。 */
855	    {
856	        int cap_try = 0;
857	        int cap_rc;
858	        while ((cap_rc = voice_capture_open(&capture, g_voice.config.capture_device,
859	                                            DOUBAO_CAPTURE_RATE, DOUBAO_CAPTURE_CHANNELS,
860	                                            DOUBAO_CAPTURE_BITS)) < 0 &&
861	               cap_try < 6 && !is_shutdown()) {
862	            usleep(100 * 1000);
863	            cap_try++;
864	        }
865	        if (cap_rc < 0) {
866	            exit_reason = "capture open failed";
867	            set_state(DOUBAO_VOICE_ERROR, "麦克风不可用");
868	            goto done;
869	        }
870	    }
871	
872	    set_state(DOUBAO_VOICE_LISTENING, NULL);
873	    started_ms = now_ms();  /* 开口等待从麦克风真正可读后开始，不计确认音/建连耗时 */
874	    DOUBAO_LOG("wake half-duplex: waiting for speech");
875	    while (!is_shutdown()) {
876	        /* 音乐抢占等外部中止:立即结束本半双工轮释放设备(此阶段尚无 TTS 在播,
877	         * 直接收尾即可)。连接健康则 done 段保留连接供复用。 */
878	        if (take_stop_playback()) {
879	            exit_reason = "stopped by user";
880	            goto done;
881	        }
882	        if (take_abort_playback()) {
883	            exit_reason = "aborted (music preempt)";
884	            goto done;
885	        }
886	        uint64_t elapsed = now_ms() - started_ms;
887	        ret = voice_capture_read_packet(capture, audio, sizeof(audio));
888	        if (ret == -EAGAIN)
889	            continue;
890	        if (ret != (int)sizeof(audio)) {
891	            exit_reason = "capture read failed";
892	            set_state(DOUBAO_VOICE_ERROR, "语音采集异常");
893	            goto done;
894	        }
895	
896	        unsigned energy = frame_energy(audio, sizeof(audio));
897	        if (!speech_started) {
898	            size_t oldest = preroll_count == DOUBAO_WAKE_PREROLL_FRAMES
899	                            ? preroll_next : 0;
900	
901	            memcpy(preroll[preroll_next], audio, sizeof(audio));
902	            preroll_next = (preroll_next + 1) % DOUBAO_WAKE_PREROLL_FRAMES;
903	            if (preroll_count < DOUBAO_WAKE_PREROLL_FRAMES)
904	                preroll_count++;
905	
906	            if (energy > DOUBAO_WAKE_VAD_ON_THRESHOLD)
907	                onset_run++;
908	            else
909	                onset_run = 0;
910	            if (onset_run < DOUBAO_WAKE_VAD_ON_FRAMES) {
911	                if (elapsed >= DOUBAO_WAKE_SPEECH_TIMEOUT_MS) {
912	                    exit_reason = "speech onset timeout";
913	                    set_state(DOUBAO_VOICE_IDLE, "未检测到语音");
914	                    goto done;
915	                }
916	                continue;
917	            }
918	            speech_started = true;
919	            begin_turn_snapshot();
920	            set_state(DOUBAO_VOICE_RECORDING, NULL);
921	            DOUBAO_LOG("wake half-duplex: speech onset energy=%u preroll=%zums",
922	                       energy, preroll_count * DOUBAO_CAPTURE_PACKET_MS);
923	            for (size_t i = 0; i < preroll_count; i++) {
924	                size_t index = (oldest + i) % DOUBAO_WAKE_PREROLL_FRAMES;
925	                if (send_audio(transport, session_id, preroll[index],
926	                               sizeof(preroll[index])) < 0) {
927	                    exit_reason = "preroll send failed";
928	                    set_state(DOUBAO_VOICE_ERROR, "语音发送失败");
929	                    keep_conn = false;
930	                    goto done;
931	                }
932	            }
933	            continue;
934	        }
935	
936	        if (send_audio(transport, session_id, audio, sizeof(audio)) < 0) {
937	            exit_reason = "audio send failed";
938	            set_state(DOUBAO_VOICE_ERROR, "语音发送失败");
939	            keep_conn = false;
940	            goto done;
941	        }
942	        if (energy <= DOUBAO_WAKE_VAD_ON_THRESHOLD)
943	            silence_run++;
944	        else
945	            silence_run = 0;
946	        if (silence_run >= DOUBAO_WAKE_VAD_SILENCE_FRAMES) {
947	            exit_reason = "speech ended by silence";
948	            break;
949	        }
950	        if (elapsed >= DOUBAO_WAKE_MAX_RECORD_MS) {
951	            exit_reason = "max record duration";
952	            break;
953	        }
954	    }
955	
956	    if (capture) {
957	        voice_capture_close(capture);
958	        capture = NULL;
959	    }
960	    if (is_shutdown())
961	        goto done;
962	    set_state(DOUBAO_VOICE_WAITING_RESPONSE, NULL);
963	    if (send_json(transport, DOUBAO_EVENT_END_ASR, session_id, "{}") < 0) {
964	        exit_reason = "END_ASR send failed";
965	        set_state(DOUBAO_VOICE_ERROR, "结束识别失败");
966	        keep_conn = false;
967	        goto done;
968	    }
969	
970	    for (;;) {
971	        /* 用户暂停:结束本轮但保留健康 WebSocket，下一次可零等待复用。 */
972	        if (take_stop_playback()) {
973	            if (player) { voice_player_abort(player); player = NULL; }
974	            discard = true;
975	            exit_reason = "stopped by user";
976	            goto done;
977	        }
978	        /* 音乐抢占等外部中止:立即停播在播 TTS 并收尾本轮,尽快释放 plughw:0,0。 */
979	        if (take_abort_playback()) {
980	            if (player) { voice_player_abort(player); player = NULL; }
981	            discard = true;                  /* 丢弃残留/滞后 TTS,不再重开 player */
982	            /* 不保留连接:服务端此刻正发 TTS 队列,finish_session_keep_connection
983	             * 要 drain 到 SESSION_FINISHED 才返回(数百 ms~数秒),会把 set_state(IDLE)
984	             * 挡在后面,音乐 STOPPING 等 IDLE 可能 5s 超时不播。走快速关闭分支让
985	             * IDLE 立即到,下次唤醒重建连接(abort 低频,可接受)。 */
986	            keep_conn = false;
987	            exit_reason = "aborted (music preempt)";
988	            break;
989	        }
990	        /* Keep wake reply abortable while waiting for its first server packet. */
991	        int timeout = chat_ended ? DOUBAO_DRAIN_TIMEOUT_MS : 200;
992	        ret = voice_transport_receive(transport, &opcode, received, sizeof(received), timeout);
993	        if (ret == 0) {
994	            if (chat_ended) {
995	                exit_reason = "reply drain complete";
996	                break;
997	            }
998	            continue;
999	        }
1000	        if (ret < 0) {
1001	            exit_reason = "reply transport failed";
1002	            set_state(DOUBAO_VOICE_ERROR, "等待豆包回复超时");
1003	            keep_conn = false;
1004	            goto done;
1005	        }
1006	        if (opcode != VOICE_WS_BINARY ||
1007	            doubao_protocol_decode(received, (size_t)ret, &packet) < 0)
1008	            continue;
1009	        handle_fd(&packet, transport, &player, &turn_open, &chat_ended, &last_audio_ms, &discard, &tts_ended);
1010	        if (packet.kind == DOUBAO_PACKET_ERROR) {
1011	            exit_reason = "service error";
1012	            keep_conn = false;
1013	            goto done;
1014	        }
1015	        /* 收尾:收到 TTS_ENDED(359)即刻收尾(voice_player_close 内部 drain 播完
1016	         * 尾音),独立于 chat_ended(见 session_loop (C) 分支对孤儿 player 的说明);
1017	         * 359 异常未到时,退回 CHAT_ENDED 后静默 DRAIN 超时兜底。 */
1018	        if (player &&
1019	            (tts_ended ||
1020	             (chat_ended && now_ms() - last_audio_ms > DOUBAO_DRAIN_TIMEOUT_MS))) {
1021	            exit_reason = tts_ended ? "reply complete (tts_ended)"
1022	                                    : "reply playback complete";
1023	            break;
1024	        }
1025	    }
1026	
1027	done:
1028	    DOUBAO_LOG("wake half-duplex: finished (%s), speech_started=%d", exit_reason,
1029	               speech_started);
1030	    if (player)
1031	        voice_player_close(player);
1032	    if (capture)
1033	        voice_capture_close(capture);
1034	    if (transport) {
1035	        /* 连接健康则只结束 Session、保留连接供 worker 复用(下次唤醒零建连);
1036	         * 若连接已失效则彻底关闭,由 worker 重连。 */
1037	        if (keep_conn && !is_shutdown() &&
1038	            finish_session_keep_connection(transport, session_id) == 0) {
1039	            *transport_io = transport;
1040	        } else {
1041	            (void)send_json(transport, DOUBAO_EVENT_FINISH_SESSION, session_id, "{}");
1042	            (void)send_json(transport, DOUBAO_EVENT_FINISH_CONNECTION, session_id, "{}");
1043	            voice_transport_close(transport);
1044	            *transport_io = NULL;
1045	        }
1046	    } else {
1047	        *transport_io = NULL;
1048	    }
1049	    if (!is_shutdown()) {
1050	        set_state(DOUBAO_VOICE_IDLE, NULL);
1051	        notify_wake_control(true);
1052	    }
1053	    return RC_STOP;
1054	}
