10	#include <time.h>
11	#include <unistd.h>
12	
13	#define WAKE_REPLY_DEVICE "default"
14	#define WAKE_REPLY_PCM_RATE 16000
15	#define WAKE_REPLY_CHANNELS 1
16	#define WAKE_REPLY_PERIOD_MS 20
17	#define WAKE_REPLY_BUFFER_MS 60
18	
19	static pthread_mutex_t g_random_mutex = PTHREAD_MUTEX_INITIALIZER;
20	static unsigned int g_random_state;
21	static int g_last_index = -1;
22	
23	static uint64_t now_ms(void)
24	{
25	    struct timespec ts;
26	
27	    clock_gettime(CLOCK_MONOTONIC, &ts);
28	    return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
29	}
30	
31	static unsigned int next_random(void)
32	{
33	    struct timespec ts;
34	    unsigned int value;
35	
36	    pthread_mutex_lock(&g_random_mutex);
37	    if (g_random_state == 0) {
38	        clock_gettime(CLOCK_MONOTONIC, &ts);
39	        g_random_state = (unsigned int)ts.tv_sec ^ (unsigned int)ts.tv_nsec ^
40	                         (unsigned int)getpid();
41	        if (g_random_state == 0)
42	            g_random_state = 1;
43	    }
44	    g_random_state = g_random_state * 1103515245u + 12345u;
45	    value = g_random_state;
46	    pthread_mutex_unlock(&g_random_mutex);
47	    return value;
48	}
