50	static int open_reply_pcm(snd_pcm_t **out)
51	{
52	    snd_pcm_t *pcm = NULL;
53	    snd_pcm_hw_params_t *hardware;
54	    snd_pcm_sw_params_t *software;
55	    unsigned int rate = WAKE_REPLY_PCM_RATE;
56	    snd_pcm_uframes_t period = rate * WAKE_REPLY_PERIOD_MS / 1000;
57	    snd_pcm_uframes_t buffer = rate * WAKE_REPLY_BUFFER_MS / 1000;
58	    int direction = 0;
59	    int ret;
60	
61	    ret = snd_pcm_open(&pcm, WAKE_REPLY_DEVICE, SND_PCM_STREAM_PLAYBACK, 0);
62	    if (ret < 0)
63	        return ret;
64	
65	    snd_pcm_hw_params_alloca(&hardware);
66	    snd_pcm_hw_params_any(pcm, hardware);
67	    snd_pcm_hw_params_set_access(pcm, hardware, SND_PCM_ACCESS_RW_INTERLEAVED);
68	    snd_pcm_hw_params_set_format(pcm, hardware, SND_PCM_FORMAT_S16_LE);
69	    snd_pcm_hw_params_set_channels(pcm, hardware, WAKE_REPLY_CHANNELS);
70	    snd_pcm_hw_params_set_rate_near(pcm, hardware, &rate, &direction);
71	    snd_pcm_hw_params_set_period_size_near(pcm, hardware, &period, &direction);
72	    snd_pcm_hw_params_set_buffer_size_near(pcm, hardware, &buffer);
73	    ret = snd_pcm_hw_params(pcm, hardware);
74	    if (ret < 0)
75	        goto fail;
76	
77	    snd_pcm_sw_params_alloca(&software);
78	    snd_pcm_sw_params_current(pcm, software);
79	    snd_pcm_sw_params_set_start_threshold(pcm, software, period);
80	    snd_pcm_sw_params_set_avail_min(pcm, software, period);
81	    ret = snd_pcm_sw_params(pcm, software);
82	    if (ret < 0)
83	        goto fail;
84	    ret = snd_pcm_prepare(pcm);
85	    if (ret < 0)
86	        goto fail;
87	
88	    *out = pcm;
89	    return 0;
90	
91	fail:
92	    snd_pcm_close(pcm);
93	    return ret;
94	}
95	
96	static int play_pcm(snd_pcm_t *pcm, const uint8_t *data, size_t size)
97	{
98	    const int16_t *samples = (const int16_t *)data;
99	    snd_pcm_sframes_t frames = (snd_pcm_sframes_t)(size / 2);
100	    snd_pcm_sframes_t offset = 0;
101	
102	    while (offset < frames) {
103	        snd_pcm_sframes_t written = snd_pcm_writei(pcm, samples + offset,
104	                                                    frames - offset);
105	        if (written < 0) {
106	            written = snd_pcm_recover(pcm, (int)written, 0);
107	            if (written < 0)
108	                return (int)written;
109	            continue;
110	        }
111	        offset += written;
112	    }
113	    return 0;
114	}
115	
116	int wake_reply_play_random(void)
117	{
118	    snd_pcm_t *pcm = NULL;
119	    size_t index;
120	    unsigned int fallback;
121	    uint64_t started_ms;
122	    int ret;
123	
124	    if (wake_reply_assets_count == 0)
125	        return -ENOENT;
126	    index = next_random() % wake_reply_assets_count;
127	    fallback = next_random();
128	
129	    pthread_mutex_lock(&g_random_mutex);
130	    if (wake_reply_assets_count > 1 && (int)index == g_last_index)
131	        index = (index + 1 + fallback % (wake_reply_assets_count - 1)) %
132	                wake_reply_assets_count;
133	    g_last_index = (int)index;
134	    pthread_mutex_unlock(&g_random_mutex);
135	
136	    const wake_reply_asset_t *asset = &wake_reply_assets[index];
137	    if (asset->size == 0 || (asset->size & 1) != 0)
138	        return -EINVAL;
139	
140	    started_ms = now_ms();
141	    fprintf(stderr, "wake: reply asset=%zu start\n", index + 1);
142	    ret = open_reply_pcm(&pcm);
143	    if (ret < 0) {
144	        fprintf(stderr, "wake: reply open failed: %s\n", snd_strerror(ret));
145	        return ret;
146	    }
147	    ret = play_pcm(pcm, asset->data, asset->size);
148	    if (ret == 0)
149	        ret = snd_pcm_drain(pcm);
150	    snd_pcm_close(pcm);
151	    fprintf(stderr, "wake: reply asset=%zu done elapsed=%llums ret=%d\n", index + 1,
152	            (unsigned long long)(now_ms() - started_ms), ret);
153	    return ret;
154	}
