249	int doubao_protocol_get_event(const uint8_t *json, size_t json_size)
250	{
251	  char local[64];
252	  const char *key = "\"event\":";
253	  const char *start;
254	  size_t length;
255	
256	  if (!json || json_size == 0 || json_size >= sizeof(local))
257	    {
258	      return 0;
259	    }
260	
261	  memcpy(local, json, json_size);
262	  local[json_size] = '\0';
263	  start = strstr(local, key);
264	  if (!start)
265	    {
266	      return 0;
267	    }
268	
269	  start += strlen(key);
270	  length = strspn(start, "0123456789");
271	  return length ? (int)strtol(start, NULL, 10) : 0;
272	}
273	
274	bool doubao_protocol_get_text(const uint8_t *json, size_t json_size,
275	                              const char *key, char *output,
276	                              size_t output_size)
277	{
278	  const uint8_t *cursor;
279	  const uint8_t *end;
280	  size_t key_size;
281	  size_t written = 0;
282	
283	  if (!json || !key || !output || output_size == 0 || json_size == 0)
284	    {
285	      return false;
286	    }
287	
288	  key_size = strlen(key);
289	  cursor = json;
290	  end = json + json_size;
291	  while (cursor < end)
292	    {
293	      if (*cursor++ != '"')
294	        {
295	          continue;
296	        }
297	      if ((size_t)(end - cursor) < key_size ||
298	          memcmp(cursor, key, key_size) != 0 ||
299	          cursor + key_size >= end || cursor[key_size] != '"')
300	        {
301	          continue;
302	        }
303	      cursor += key_size + 1;
304	      while (cursor < end && isspace((unsigned char)*cursor))
305	        {
306	          cursor++;
307	        }
308	      if (cursor == end || *cursor++ != ':')
309	        {
310	          continue;
311	        }
312	      while (cursor < end && isspace((unsigned char)*cursor))
313	        {
314	          cursor++;
315	        }
316	      if (cursor == end || *cursor++ != '"')
317	        {
318	          continue;
319	        }
320	
321	      while (cursor < end && *cursor != '"')
322	        {
323	          uint8_t value = *cursor++;
324	          if (value == '\\')
325	            {
326	              if (cursor == end)
327	                {
328	                  return false;
329	                }
330	              value = *cursor++;
331	              switch (value)
332	                {
333	                  case 'b': value = '\b'; break;
334	                  case 'f': value = '\f'; break;
335	                  case 'n': value = '\n'; break;
336	                  case 'r': value = '\r'; break;
337	                  case 't': value = '\t'; break;
338	                  case 'u':
339	                    if ((size_t)(end - cursor) < 4)
340	                      {
341	                        return false;
342	                      }
343	                    cursor += 4;
344	                    value = '?';
345	                    break;
346	                  default: break;
347	                }
348	            }
349	          if (written + 1 < output_size)
350	            {
351	              output[written++] = (char)value;
352	            }
353	        }
354	      if (cursor == end)
355	        {
356	          return false;
357	        }
358	      output[written] = '\0';
359	      return true;
360	    }
361	
362	  return false;
363	}
