{
  const char *app_id;
  const char *access_token;
  const char *resource_id;
  const char *app_key;
  const char *model;
  const char *speaker;
  const char *capture_device;
  const char *playback_device;
  int tts_enabled;
} doubao_voice_config_t;

#endif /* HOME_SCENSE_DOUBAO_CONFIG_H */

