27	static void player_dequeue(unsigned long arg, struct ap_buffer_s *buffer)
28	{
29	  voice_player_t *player = (voice_player_t *)(uintptr_t)arg;
30	  ssize_t received;
31	
32	  if (!player || !buffer)
33	    {
34	      return;
35	    }
36	
37	  received = read(player->read_fd, buffer->samp, buffer->nmaxbytes);
38	  if (received <= 0)
39	    {
40	      buffer->nbytes = 0;
41	      return;
42	    }
43	
44	  buffer->nbytes = received;
45	  buffer->curbyte = 0;
46	  buffer->flags = 0;
47	  (void)nxaudio_enqbuffer(&player->audio, buffer);
48	}
