67	static void *player_thread(void *arg)
68	{
69	  voice_player_t *player = arg;
70	  struct nxaudio_callbacks_s callbacks =
71	  {
72	    player_dequeue,
73	    player_complete,
74	    player_user,
75	  };
76	  int i;
77	
78	  for (i = 0; i < player->audio.abufnum; i++)
79	    {
80	      player_dequeue((unsigned long)(uintptr_t)player, player->audio.abufs[i]);
81	    }
82	
83	  (void)nxaudio_start(&player->audio);
84	  (void)nxaudio_msgloop(&player->audio, &callbacks,
85	                        (unsigned long)(uintptr_t)player);
86	  player->running = 0;
87	  return NULL;
88	}
