90	int voice_player_open(voice_player_t **out, const char *device,
91	                      uint32_t sample_rate, uint8_t channels,
92	                      uint8_t bits_per_sample)
93	{
94	  voice_player_t *player;
95	  int fds[2];
96	  int ret;
97	
98	  if (!out || !device)
99	    {
100	      return -EINVAL;
101	    }
102	
103	  player = calloc(1, sizeof(*player));
104	  if (!player)
105	    {
106	      return -ENOMEM;
107	    }
108	  player->read_fd = -1;
109	  player->write_fd = -1;
110	
111	  if (pipe(fds) < 0)
112	    {
113	      free(player);
114	      return -errno;
115	    }
116	  player->read_fd = fds[0];
117	  player->write_fd = fds[1];
118	
119	  ret = init_nxaudio_devname(&player->audio, sample_rate, bits_per_sample,
120	                             channels, device, "/doubao_player");
121	  if (ret < 0)
122	    {
123	      voice_player_close(player);
124	      return ret;
125	    }
126	  player->audio_initialized = 1;
127	
128	  player->running = 1;
129	  ret = pthread_create(&player->thread, NULL, player_thread, player);
130	  if (ret != 0)
131	    {
132	      voice_player_close(player);
133	      return -ret;
134	    }
135	
136	  *out = player;
137	  return 0;
138	}
