140	int voice_player_write(voice_player_t *player, const uint8_t *data,
141	                       size_t size)
142	{
143	  size_t written = 0;
144	
145	  if (!player || !data)
146	    {
147	      return -EINVAL;
148	    }
149	
150	  while (written < size)
151	    {
152	      ssize_t ret = write(player->write_fd, data + written, size - written);
153	      if (ret <= 0)
154	        {
155	          return -errno;
156	        }
157	      written += ret;
158	    }
159	
160	  return 0;
161	}
162	
163	void voice_player_close(voice_player_t *player)
164	{
165	  if (!player)
166	    {
167	      return;
168	    }
169	
170	  if (player->write_fd >= 0)
171	    {
172	      close(player->write_fd);
173	      player->write_fd = -1;
174	    }
175	  /* 必须无条件发 AUDIO_MSG_STOP:nxaudio_msgloop 只在收到 STOP 时才退出,
176	   * 播放自然结束(AUDIO_MSG_COMPLETE)只把回调里的 running 置 0,并不会让
177	   * msgloop 跳出——它会继续阻塞在 mq_receive。若因 running==0 而跳过
178	   * nxaudio_stop,后面的 pthread_join 会永久等待,worker 线程卡在
179	   * "Waiting MQ empty",整个语音功能死锁。故这里始终 stop。 */
180	  if (player->audio_initialized)
181	    {
182	      (void)nxaudio_stop(&player->audio);
183	    }
184	  if (player->thread)
185	    {
186	      (void)pthread_join(player->thread, NULL);
187	    }
188	  if (player->read_fd >= 0)
189	    {
190	      close(player->read_fd);
191	    }
192	  if (player->audio_initialized)
193	    {
194	      fin_nxaudio(&player->audio);
195	    }
196	  free(player);
197	}
